// Deep link into one changelog entry from a fresh tab (the "Learn more" button
// on the what's-new modal opens "#updates/update-2026-06-16" in a new tab).
function readUpdatesAnchorFromHash(): string | null {
  if (typeof window === "undefined") return null;
  const match = window.location.hash.match(/^#updates\/(update-\d{4}-\d{2}-\d{2})$/);
  return match ? match[1] : null;
}

