function programPages(productId: OnboardingProductId) {
  const program = programRegistry[productId];
  return [program.primaryPage, ...program.relatedPages];
}

function selectedProductLabels(selectedProductIds: OnboardingProductId[]) {
  return selectedProductIds.flatMap((productId) => {
    const label = onboardingProductOptions.find((product) => product.id === productId)?.label;
    return label ? [label] : [];
  });
}

// ---- Release tags in the navigation -----------------------------------------
// HubSpot-style: a page that a recent product update introduced (see
// UpdateEntryData.introduces) wears a "New" pill for NEW_TAG_DAYS after that
// update, and pages still in beta wear "Beta" — in the rail flyout, on the hub
// icon, in Create new and next to the page title. Adding a new category is just
// `introduces: [page]` on its release entry (plus BETA_PAGES while it's beta).
const NEW_TAG_DAYS = 30;
const BETA_PAGES: ReadonlySet<Page> = new Set<Page>(["companies", "deals"]);
type PageReleaseTag = "New" | "Beta";
function pageReleaseTag(page: Page, today = new Date()): PageReleaseTag | null {
  if (BETA_PAGES.has(page)) return "Beta";
  const cutoff = today.getTime() - NEW_TAG_DAYS * 86_400_000;
  const recentlyIntroduced = UPDATE_ENTRIES.some(
    (entry) => entry.introduces?.includes(page) && new Date(`${entry.dateTime}T00:00:00`).getTime() >= cutoff
  );
  return recentlyIntroduced ? "New" : null;
}
function PageReleaseTag({ page }: { page: Page }) {
  const tag = pageReleaseTag(page);
  return tag ? <span className={`hs-page-tag ${tag.toLowerCase()}`}>{tag}</span> : null;
}

// ---- Paid add-on programs ---------------------------------------------------
// Programs that aren't part of the workspace yet get a HubSpot-style up-arrow
// in the navigation: hovering explains the add-on, choosing it prompts where
// to buy it (Settings → Billing → Add-ons). AI ships in every tier, so it
// never locks a page.
const ADD_ON_PAGE_LOCKS: Partial<Record<Page, OnboardingProductId>> = {
  map: "map-field-ops",
  equipment: "equipment-tracking",
  timecard: "time-cards"
};
type AddOnCatalogEntry = { price: string; unit: string; includedIn: ProductPlanId[]; pitch: string };
const ADD_ON_CATALOG: Record<OnboardingProductId, AddOnCatalogEntry> = {
  "map-field-ops": {
    price: "$12",
    unit: "per user / month",
    includedIn: ["business", "enterprise"],
    pitch: "Live vehicle and equipment locations, traffic routing, and field operations on one map."
  },
  "equipment-tracking": {
    price: "$9",
    unit: "per user / month",
    includedIn: ["business", "enterprise"],
    pitch: "Assignment, utilization, and maintenance status for every machine in the fleet."
  },
  "time-cards": {
    price: "$8",
    unit: "per user / month",
    includedIn: ["business", "enterprise"],
    pitch: "Crew hours logged against jobs and approved for payroll and job costing."
  },
  "schedule-ai": {
    price: "$15",
    unit: "per user / month",
    includedIn: ["pro", "business", "enterprise"],
    pitch: "Conflict detection, plain-language answers, and recovery suggestions across the schedule."
  }
};
function isAddOnUnlocked(productId: OnboardingProductId, selectedProductIds: OnboardingProductId[], planId: ProductPlanId | ""): boolean {
  return selectedProductIds.includes(productId) || (planId !== "" && ADD_ON_CATALOG[productId].includedIn.includes(planId));
}
function joinNames(names: string[]): string {
  if (names.length <= 1) return names.join("");
  return `${names.slice(0, -1).join(", ")} and ${names[names.length - 1]}`;
}
function addOnIncludedPlanNames(productId: OnboardingProductId): string {
  return joinNames(ADD_ON_CATALOG[productId].includedIn.map((planId) => planById[planId].name));
}
// Copy for the side bubble next to a locked program in the nav flyout.
function addOnTipCopy(productId: OnboardingProductId): { title: string; body: string } {
  const program = programRegistry[productId];
  const catalog = ADD_ON_CATALOG[productId];
  return {
    title: `${program.label} add-on`,
    body: `This program is part of the ${program.label} add-on — ${catalog.price} ${catalog.unit}, or included with the ${addOnIncludedPlanNames(productId)} plans. Choose it to see where to get it.`
  };
}

