function defaultProjectTargetCompletion() {
  const date = new Date();
  date.setDate(date.getDate() + 90);
  return toLocalIsoDate(date);
}

function initialProjectInput(project: Project | undefined, users: User[]): CreateProjectInput {
  const defaultManagerId = users.find((user) => user.role === "Project Manager" || user.role === "Superintendent")?.id ?? "";

  return {
    name: project?.name ?? "",
    location: project?.location ?? "",
    address: project?.address ?? "",
    type: project?.type ?? "Commercial",
    contractType: project?.contractType ?? "Fixed Price",
    managerId: project?.managerId ?? defaultManagerId,
    targetCompletion: project?.targetCompletion ?? defaultProjectTargetCompletion(),
    percentComplete: project?.percentComplete ?? 0,
    status: project?.status ?? "Not Started",
    scheduleHealth: project?.scheduleHealth ?? "On Track",
    // left undefined for a new project — "not priced yet", not zero
    value: project?.value
  };
}

