const planById = Object.fromEntries(productPlans.map((plan) => [plan.id, plan])) as Record<ProductPlanId, ProductPlan>;

type BillingPeriod = "monthly" | "yearly";
const YEARLY_DISCOUNT = 0.2; // yearly billing saves 20%

function formatPlanUsd(value: number): string {
  return Number.isInteger(value) ? `$${value}` : `$${value.toFixed(2)}`;
}

// Resolves the displayed price + note for a plan given the selected billing period.
// Yearly shows the discounted effective per-user/month rate (20% off) billed annually.
function planPricing(plan: ProductPlan, period: BillingPeriod): { price: string; note: string; save?: string } {
  if (plan.priceMonthly === null) {
    return { price: plan.price, note: plan.priceNote };
  }
  if (plan.priceMonthly === 0) {
    return { price: "$0", note: period === "yearly" ? "Per user / mo · billed yearly" : "Per user / month" };
  }
  if (period === "yearly") {
    const monthly = plan.priceMonthly * (1 - YEARLY_DISCOUNT);
    return {
      price: formatPlanUsd(monthly),
      note: "Per user / mo · billed yearly",
      save: `Save 20% vs ${formatPlanUsd(plan.priceMonthly)}/mo`
    };
  }
  return { price: formatPlanUsd(plan.priceMonthly), note: "Per user / month" };
}

// Animated dollar amount — tweens (counts) from the previous value to the new one
// whenever it changes, e.g. when the Monthly/Yearly toggle flips.
function PriceCounter({ value }: { value: number }) {
  const ref = useRef<HTMLSpanElement>(null);
  const prev = useRef(value);
  const fmt = (v: number) => (Number.isInteger(value) ? Math.round(v).toString() : v.toFixed(2));
  useEffect(() => {
    const node = ref.current;
    if (!node) return;
    const from = prev.current;
    prev.current = value;
    if (from === value) {
      node.textContent = fmt(value);
      return;
    }
    const controls = animate(from, value, {
      duration: 0.6,
      ease: [0.22, 1, 0.36, 1],
      onUpdate: (v) => {
        node.textContent = fmt(v);
      }
    });
    return () => controls.stop();
    // eslint-disable-next-line react-hooks/exhaustive-deps -- `fmt` only formats; a new formatter must not restart the count
  }, [value]);
  return <span ref={ref}>{fmt(value)}</span>;
}

// Plan price display: paid plans render "$" + the animated counter; Custom stays static.
function AnimatedPlanPrice({ plan, period }: { plan: ProductPlan; period: BillingPeriod }) {
  if (plan.priceMonthly === null) return <>{plan.price}</>;
  const value = period === "yearly" ? plan.priceMonthly * (1 - YEARLY_DISCOUNT) : plan.priceMonthly;
  return (
    <>
      $<PriceCounter value={value} />
    </>
  );
}

// Monthly / Yearly toggle with a pill indicator that slides (tweens) between the two options.
function BillingToggle({
  value,
  onChange,
  className = ""
}: {
  value: BillingPeriod;
  onChange: (period: BillingPeriod) => void;
  className?: string;
}) {
  const monthlyRef = useRef<HTMLButtonElement>(null);
  const yearlyRef = useRef<HTMLButtonElement>(null);
  const [indicator, setIndicator] = useState({ left: 0, width: 0 });
  useEffect(() => {
    const el = value === "monthly" ? monthlyRef.current : yearlyRef.current;
    if (el) setIndicator({ left: el.offsetLeft, width: el.offsetWidth });
  }, [value]);
  return (
    <div className={`plans-billing ${className}`.trim()} role="tablist" aria-label="Billing period">
      <span
        className="plans-billing-indicator"
        aria-hidden="true"
        style={{ transform: `translateX(${indicator.left}px)`, width: indicator.width }}
      />
      <button
        ref={monthlyRef}
        type="button"
        role="tab"
        aria-selected={value === "monthly"}
        className={`plans-billing-opt ${value === "monthly" ? "on" : ""}`}
        onClick={() => onChange("monthly")}
      >
        Monthly
      </button>
      <button
        ref={yearlyRef}
        type="button"
        role="tab"
        aria-selected={value === "yearly"}
        className={`plans-billing-opt ${value === "yearly" ? "on" : ""}`}
        onClick={() => onChange("yearly")}
      >
        Yearly <span className="plans-billing-save">Save 20%</span>
      </button>
    </div>
  );
}
