function WxCounter({ value }: { value: number }) {
  const ref = useRef<HTMLElement>(null);
  const [display, setDisplay] = useState(0);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    let raf = 0;
    let started = false;
    const prefersReduced =
      typeof window !== "undefined" &&
      typeof window.matchMedia === "function" &&
      window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    const run = () => {
      if (started) return;
      started = true;
      // Reduced motion (or no rAF): snap to the final value — never leave it at 0.
      if (prefersReduced || typeof requestAnimationFrame === "undefined") {
        setDisplay(value);
        return;
      }
      const start = performance.now();
      const duration = 1300;
      const tick = (now: number) => {
        const progress = Math.min(1, (now - start) / duration);
        const eased = 1 - Math.pow(1 - progress, 3);
        setDisplay(Math.round(value * eased));
        if (progress < 1) raf = requestAnimationFrame(tick);
      };
      raf = requestAnimationFrame(tick);
    };

    // No IntersectionObserver (older/embedded browsers) → just run it.
    if (typeof IntersectionObserver === "undefined") {
      run();
      return () => cancelAnimationFrame(raf);
    }

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting && !started) {
            run();
            observer.disconnect();
          }
        });
      },
      { threshold: 0.35 }
    );
    observer.observe(el);

    // Safety net: if the observer never fires (some headless/embedded webviews,
    // odd layouts, or a stat taller than the viewport), start after a beat so the
    // number always lands on its value instead of sticking at 0.
    const fallback = window.setTimeout(() => {
      if (!started) {
        run();
        observer.disconnect();
      }
    }, 1600);

    return () => {
      observer.disconnect();
      cancelAnimationFrame(raf);
      clearTimeout(fallback);
    };
  }, [value]);
  return <b ref={ref}>{display}</b>;
}

function WxMagnetic({
  children,
  className,
  onClick,
  ariaLabel,
  strength = 0.34,
  disabled = false
}: {
  children: ReactNode;
  className?: string;
  onClick?: () => void;
  ariaLabel?: string;
  strength?: number;
  disabled?: boolean;
}) {
  const ref = useRef<HTMLButtonElement>(null);
  const handleMove = (event: MouseEvent<HTMLButtonElement>) => {
    const el = ref.current;
    if (!el || disabled) return;
    const rect = el.getBoundingClientRect();
    const x = event.clientX - (rect.left + rect.width / 2);
    const y = event.clientY - (rect.top + rect.height / 2);
    el.style.transform = `translate(${x * strength}px, ${y * strength}px)`;
  };
  const reset = () => {
    if (ref.current) ref.current.style.transform = "";
  };
  return (
    <button
      ref={ref}
      type="button"
      className={className}
      onClick={onClick}
      onMouseMove={handleMove}
      onMouseLeave={reset}
      aria-label={ariaLabel}
      disabled={disabled}
    >
      {children}
    </button>
  );
}

/* "Bloom Field" mesh gradient (21st.dev "Pipo"): three colour blobs, each a
   radial-gradient anchored at its own point over a paper backdrop, with a grain
   texture blended on top. Animated from a requestAnimationFrame clock: every
   modulation is exactly zero at ph = 0 (sin(x + p) - sin(p)), so motion starts
   from the resting frame instead of snapping. Values are never rounded — a
   rounded centre steps visibly at this speed. Blobs pause while off-screen. */
const BLOOM_GRAIN =
  "url(\"data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' width='120' height='120'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='2' stitchTiles='stitch'/></filter><rect width='100%' height='100%' filter='url(%23n)' opacity='0.305'/></svg>\")";
const BLOOM_BLOBS: Array<{ rgb: [number, number, number]; x: number; y: number; r: number }> = [
  { rgb: [230, 176, 147], x: 68.1, y: 46.03, r: 41.1 }, // Apricot
  { rgb: [163, 206, 255], x: 25.17, y: 75.99, r: 44.6 }, // Sky blue
  { rgb: [250, 249, 239], x: 53.11, y: 12.71, r: 66.65 } // Paper
];
/** A static per-blob phase from the seed: continuous in time, different per blob. */
function bloomPhase(seed: number, index: number, salt: number) {
  const v = Math.sin(seed * 12.9898 + index * 78.233 + salt * 37.719) * 43758.5453;
  return (v - Math.floor(v)) * Math.PI * 2;
}
function bloomBackground(seed: number, ph: number) {
  const amt = 0.72;
  const dir = 1;
  const spin = ph * dir;
  const layers = BLOOM_BLOBS.map((blob, i) => {
    const p = bloomPhase(seed, i, 1);
    const p2 = bloomPhase(seed, i, 2);
    const x = blob.x + (Math.sin(spin * 0.55 + p) - Math.sin(p)) * 14 * amt;
    const y = blob.y + (Math.sin(spin * 0.43 + p2) - Math.sin(p2)) * 14 * amt;
    const [r, g, b] = blob.rgb;
    const stop = (alpha: number, at: number) => `rgba(${r}, ${g}, ${b}, ${alpha}) ${at}%`;
    return `radial-gradient(circle at ${x}% ${y}%, ${stop(1, 0)}, ${stop(0.844, blob.r * 0.25)}, ${stop(0.5, blob.r * 0.5)}, ${stop(0.156, blob.r * 0.75)}, ${stop(0, blob.r)})`;
  });
  return `${BLOOM_GRAIN}, ${layers.join(", ")}`;
}

function WxBloomField({ seed = 1, className = "" }: { seed?: number; className?: string }) {
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const paint = (ph: number) => {
      el.style.backgroundImage = bloomBackground(seed, ph);
    };
    paint(0);
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    let raf = 0;
    let running = false;
    let start = 0;
    let pausedAt = 0; // keeps the clock continuous across pause/resume
    const tick = (now: number) => {
      if (!start) start = now;
      const t = (now - start) / 1000;
      paint(t * 0.86);
      raf = requestAnimationFrame(tick);
    };
    const observer = new IntersectionObserver(([entry]) => {
      if (entry.isIntersecting && !running) {
        running = true;
        if (pausedAt) start += performance.now() - pausedAt;
        raf = requestAnimationFrame(tick);
      } else if (!entry.isIntersecting && running) {
        running = false;
        pausedAt = performance.now();
        cancelAnimationFrame(raf);
      }
    });
    observer.observe(el);
    return () => {
      observer.disconnect();
      cancelAnimationFrame(raf);
    };
  }, [seed]);
  return <div ref={ref} className={`wx-bloom ${className}`.trim()} aria-hidden="true" />;
}

function WxTilt({
  children,
  className,
  style,
  id,
  max = 10,
  restRx = 0,
  restRy = 0
}: {
  children: ReactNode;
  className?: string;
  style?: CSSProperties;
  id?: string;
  max?: number;
  restRx?: number;
  restRy?: number;
}) {
  const ref = useRef<HTMLDivElement>(null);
  const handleMove = (event: MouseEvent<HTMLDivElement>) => {
    const el = ref.current;
    if (!el) return;
    const rect = el.getBoundingClientRect();
    const px = (event.clientX - rect.left) / rect.width;
    const py = (event.clientY - rect.top) / rect.height;
    el.style.setProperty("--rx", `${restRx + (px - 0.5) * 2 * max}deg`);
    el.style.setProperty("--ry", `${restRy + (0.5 - py) * 2 * max}deg`);
    el.style.setProperty("--gx", `${px * 100}%`);
    el.style.setProperty("--gy", `${py * 100}%`);
  };
  const reset = () => {
    const el = ref.current;
    if (!el) return;
    el.style.setProperty("--rx", `${restRx}deg`);
    el.style.setProperty("--ry", `${restRy}deg`);
  };
  return (
    <div ref={ref} className={className} style={style} id={id} onMouseMove={handleMove} onMouseLeave={reset}>
      {children}
    </div>
  );
}

function WxTypewriter({ normal, em }: { normal: string; em: string }) {
  const full = normal + em;
  const reduced = typeof window !== "undefined" && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  const [count, setCount] = useState(reduced ? full.length : 0);
  const [done, setDone] = useState(reduced);
  useEffect(() => {
    if (reduced) return;
    let index = 0;
    let handle = 0;
    const step = () => {
      index += 1;
      setCount(index);
      if (index < full.length) {
        handle = window.setTimeout(step, 28 + Math.random() * 30);
      } else {
        setDone(true);
      }
    };
    handle = window.setTimeout(step, 350);
    return () => window.clearTimeout(handle);
  }, [full.length, reduced]);

  const normalShown = normal.slice(0, Math.min(count, normal.length));
  const emShown = count > normal.length ? em.slice(0, count - normal.length) : "";
  return (
    <>
      <span className="wx-type-ghost" aria-hidden="true">
        {normal}
        <em>{em}</em>
      </span>
      <span className="wx-type-real" aria-hidden="true">
        {normalShown}
        <em>{emShown}</em>
        <span className={`wx-caret${done ? " done" : ""}`} aria-hidden="true" />
      </span>
      <span className="wx-type-a11y">{full}</span>
    </>
  );
}

// Interchangeable closers for the hero — each finishes "Where crews, projects,
// and schedules ___" with the same "move together" meaning (stable ref so the
// rotator effect below doesn't restart on every render).
const heroTaglinePhrases = ["move together.", "stay in sync.", "flow as one.", "run on time.", "stay on track.", "move as one."];

// Types the static prefix once, then endlessly cycles the emphasis phrase
// (type → hold → delete → next). Reuses WxTypewriter's ghost/real/caret markup
// so it inherits the exact hero styling — blue `em`, sizing, and caret.
function WxRotatingHeadline({ prefix, phrases }: { prefix: string; phrases: string[] }) {
  const reduced = typeof window !== "undefined" && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  const longest = phrases.reduce((a, b) => (b.length > a.length ? b : a), "");
  const [prefixLen, setPrefixLen] = useState(reduced ? prefix.length : 0);
  const [index, setIndex] = useState(0);
  const [phraseLen, setPhraseLen] = useState(reduced ? phrases[0].length : 0);
  const [deleting, setDeleting] = useState(false);

  useEffect(() => {
    if (reduced) return;
    let handle = 0;
    if (prefixLen < prefix.length) {
      // Phase 1: type the fixed prefix once.
      handle = window.setTimeout(() => setPrefixLen((n) => n + 1), 26 + Math.random() * 26);
    } else if (!deleting && phraseLen < phrases[index].length) {
      // Phase 2: type the current phrase.
      handle = window.setTimeout(() => setPhraseLen((n) => n + 1), 42 + Math.random() * 34);
    } else if (!deleting) {
      // Phase 3: hold the completed phrase, then delete.
      handle = window.setTimeout(() => setDeleting(true), 1900);
    } else if (phraseLen > 0) {
      // Phase 4: delete the current phrase.
      handle = window.setTimeout(() => setPhraseLen((n) => n - 1), 24 + Math.random() * 18);
    } else {
      // Phase 5: advance to the next phrase and type again.
      handle = window.setTimeout(() => {
        setDeleting(false);
        setIndex((i) => (i + 1) % phrases.length);
      }, 260);
    }
    return () => window.clearTimeout(handle);
  }, [prefixLen, phraseLen, deleting, index, prefix.length, phrases, reduced]);

  return (
    <>
      <span className="wx-type-ghost" aria-hidden="true">
        {prefix}
        <em>{longest}</em>
      </span>
      <span className="wx-type-real" aria-hidden="true">
        {prefix.slice(0, prefixLen)}
        <em>{phrases[index].slice(0, phraseLen)}</em>
        <span className="wx-caret" aria-hidden="true" />
      </span>
      <span className="wx-type-a11y">{prefix + phrases[0]}</span>
    </>
  );
}

