// Decorative signature visual for the login/signup aside: a "live schedule" that
// assembles itself, with one double-booked block that moves into a free slot.
// Rendered as pure CSS animation (see the .acct-viz block in account-redesign.css);
// every animation shares one 12s period so the per-block animation-delay stagger
// stays locked on every repeat. `fix` marks the double-booked block.
type AcctVizJob = { left: number; width: number; tone: "blue" | "cyan" | "violet"; delayIQ: number; fix?: boolean };
const ACCT_VIZ_LANES: { crew: string; jobs: AcctVizJob[] }[] = [
  {
    crew: "Framing",
    jobs: [
      { left: 2, width: 30, tone: "blue", delayIQ: 0.2 },
      { left: 40, width: 26, tone: "cyan", delayIQ: 0.55 }
    ]
  },
  {
    crew: "Concrete",
    jobs: [
      { left: 6, width: 24, tone: "violet", delayIQ: 0.9 },
      { left: 68, width: 28, tone: "blue", delayIQ: 1.25 }
    ]
  },
  {
    crew: "Electrical",
    jobs: [
      { left: 6, width: 26, tone: "cyan", delayIQ: 1.6 },
      { left: 20, width: 24, tone: "blue", delayIQ: 1.95, fix: true }
    ]
  },
  {
    crew: "Roofing",
    jobs: [
      { left: 34, width: 30, tone: "violet", delayIQ: 2.3 },
      { left: 72, width: 22, tone: "cyan", delayIQ: 2.65 }
    ]
  }
];

// Shared by every step of the auth/onboarding flow, so the branded panel reads as
// one continuous surface while the form column advances.
function AcctScheduleViz() {
  return (
    <div className="acct-viz">
      <div className="acct-viz-card">
        <div className="acct-viz-head">
          <span className="acct-viz-live" />
          <span>Live schedule</span>
          <span className="acct-viz-week">Mon &mdash; Fri</span>
        </div>
        <div className="acct-viz-lanes">
          {ACCT_VIZ_LANES.map((lane) => (
            <div className="acct-viz-lane" key={lane.crew}>
              <span className="acct-viz-crew">{lane.crew}</span>
              <span className="acct-viz-track">
                {lane.jobs.map((job, index) => (
                  <i
                    key={index}
                    className={`acct-viz-job acct-viz-job-${job.tone}${job.fix ? " is-fix" : ""}`}
                    style={{ left: `${job.left}%`, width: `${job.width}%`, animationDelay: `${job.delayIQ}s` }}
                  />
                ))}
              </span>
            </div>
          ))}
        </div>
        <span className="acct-viz-sweep" />
      </div>
    </div>
  );
}

/* Signup form fields, in the order they are validated and shown. Server-side
   validation answers with one of these names so the message lands under the
   right input (see ApiError.field). */
type SignupField = "name" | "company" | "email" | "password" | "terms";
const SIGNUP_FIELDS: SignupField[] = ["name", "company", "email", "password", "terms"];
const isSignupField = (value: string): value is SignupField => (SIGNUP_FIELDS as string[]).includes(value);
// Deliberately loose: the server does the real check; this only catches "jordan"
// or "jordan@reyes" before a round trip.
const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
// Consumer mailboxes. A signup from one still works — plenty of small
// contractors run on Gmail — but the form nudges toward a company address,
// which is what keeps the workspace with the business when people move on.
const PERSONAL_EMAIL_DOMAINS = new Set([
  "gmail.com",
  "googlemail.com",
  "yahoo.com",
  "ymail.com",
  "outlook.com",
  "hotmail.com",
  "live.com",
  "msn.com",
  "icloud.com",
  "me.com",
  "mac.com",
  "aol.com",
  "proton.me",
  "protonmail.com",
  "mail.com",
  "comcast.net",
  "att.net",
  "verizon.net"
]);
function isPersonalEmail(email: string): boolean {
  const domain = email.trim().toLowerCase().split("@")[1] ?? "";
  return PERSONAL_EMAIL_DOMAINS.has(domain);
}

function WelcomeCreateAccountPage({
  onBack,
  onSignup,
  onLoginSubmit,
  initialMode = "signup"
}: {
  onBack: () => void;
  onSignup: (input: SignupInput) => Promise<void>;
  onLoginSubmit: (input: { email: string; password: string; remember?: boolean }) => Promise<void>;
  initialMode?: "signup" | "login";
}) {
  const [mode, setMode] = useState<"signup" | "login" | "forgot">(initialMode);
  // "forgot": the email field + one button; after sending, a plain confirmation.
  const [resetSent, setResetSent] = useState(false);
  // Provider buttons exist only when the server has credentials for them.
  const [oauthProviders, setOauthProviders] = useState<Record<OAuthProvider, boolean>>({ google: false, microsoft: false });
  useEffect(() => {
    let cancelled = false;
    apiFetchOauthStatus()
      .then((status) => {
        if (!cancelled && status?.providers) setOauthProviders(status.providers);
      })
      .catch(() => undefined);
    return () => {
      cancelled = true;
    };
  }, []);
  // A provider round trip that failed comes back as "?oauth=error&reason=…".
  useEffect(() => {
    if (typeof window === "undefined") return;
    const params = new URLSearchParams(window.location.search);
    if (params.get("oauth") !== "error") return;
    const reason = params.get("reason") ?? "";
    const messages: Record<string, string> = {
      cancelled: "Sign-in was cancelled. You can try again or use your email.",
      no_account: "There's no BuildFlow account for that email yet. Create one below, or sign in with a different address.",
      email_unverified:
        "That provider hasn't confirmed the email on the account. Use an address they have verified, or sign up with your email.",
      terms_required: "Please agree to the Terms & Conditions and Privacy Policy before continuing with a provider.",
      not_configured: "That sign-in option isn't set up yet. Use your email for now.",
      state_missing: "That sign-in took too long or the browser lost track of it. Please try again.",
      state_mismatch: "That sign-in took too long or the browser lost track of it. Please try again.",
      exchange_failed: "The provider didn't complete sign-in. Please try again or use your email."
    };
    setError(messages[reason] ?? "Sign-in with that provider didn't complete. Please try again or use your email.");
    if (reason === "no_account") setMode("signup");
    window.history.replaceState(null, "", `${window.location.pathname}${window.location.hash}`);
  }, []);

  const startWithProvider = (provider: OAuthProvider) => {
    if (isSignup && !acceptTerms) {
      setFieldErrors({ terms: "Please agree to the Terms & Conditions and Privacy Policy." });
      return;
    }
    if (typeof window === "undefined") return;
    window.location.assign(apiOauthStartUrl(provider, { mode: isSignup ? "signup" : "login", acceptTerms, remember }));
  };
  const anyProvider = oauthProviders.google || oauthProviders.microsoft;
  const [name, setName] = useState("");
  const [company, setCompany] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  // Errors live under the field they belong to. `error` is only for problems
  // no single field owns (network down, wrong password on login).
  const [error, setError] = useState("");
  const [fieldErrors, setFieldErrors] = useState<Partial<Record<SignupField, string>>>({});
  const [emailTaken, setEmailTaken] = useState(false);
  const [busy, setBusy] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [acceptTerms, setAcceptTerms] = useState(false);
  // "Keep me signed in" — on by default, which matches the previous behaviour
  // (a 30-day cookie). Unchecking asks the server for a browser-session cookie,
  // so closing the browser signs this account out (shared/site computers).
  // Applies to signup as well as login.
  const [remember, setRemember] = useState(true);
  const isSignup = mode === "signup";
  const strength = passwordStrength(password, email);

  // Funnel: the form appearing in signup mode is the top of the registration funnel.
  useEffect(() => {
    if (mode === "signup") track(EVENTS.signupStarted);
  }, [mode]);

  const clearField = (field: SignupField) => {
    if (error) setError("");
    if (field === "email" && emailTaken) setEmailTaken(false);
    setFieldErrors((current) => (current[field] ? { ...current, [field]: undefined } : current));
  };

  const validate = (): Partial<Record<SignupField, string>> => {
    const next: Partial<Record<SignupField, string>> = {};
    const mail = email.trim();
    if (isSignup && !name.trim()) next.name = "Enter your name.";
    if (isSignup && company.trim().length < 2) next.company = "Enter your company name.";
    if (!mail) next.email = "Enter your email address.";
    else if (!EMAIL_PATTERN.test(mail)) next.email = "Enter a valid email address.";
    if (isSignup) {
      const problem = passwordProblem(password, mail);
      if (problem) next.password = problem;
    } else if (!password) {
      next.password = "Enter your password.";
    }
    if (isSignup && !acceptTerms) next.terms = "Please agree to the Terms & Conditions and Privacy Policy.";
    return next;
  };

  const switchToLogin = () => {
    // keep the email they typed — that is the whole point of "log in instead"
    setMode("login");
    setFieldErrors({});
    setEmailTaken(false);
    setError("");
  };

  const submit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (busy) return;
    if (mode === "forgot") {
      const mail = email.trim();
      if (!mail || !EMAIL_PATTERN.test(mail)) {
        setFieldErrors({ email: mail ? "Enter a valid email address." : "Enter the email you signed up with." });
        return;
      }
      setFieldErrors({});
      setError("");
      setBusy(true);
      try {
        await apiRequestPasswordReset(mail);
        setResetSent(true);
      } catch (err) {
        setError(err instanceof Error ? err.message : "Something went wrong. Please try again.");
      } finally {
        setBusy(false);
      }
      return;
    }
    const problems = validate();
    setFieldErrors(problems);
    if (SIGNUP_FIELDS.some((field) => problems[field])) return;
    setError("");
    setBusy(true);
    try {
      if (isSignup) {
        await onSignup({ email: email.trim(), password, name: name.trim(), orgName: company.trim(), acceptTerms: true, remember });
      } else {
        await onLoginSubmit({ email: email.trim(), password, remember });
      }
      // On success the parent navigates into the app; this component unmounts.
    } catch (err) {
      const message = err instanceof Error ? err.message : "Something went wrong. Please try again.";
      if (err instanceof ApiError && err.field && isSignupField(err.field)) {
        setFieldErrors({ [err.field]: message });
        if (err.code === "email_taken") setEmailTaken(true);
      } else {
        setError(message);
      }
      setBusy(false);
    }
  };

  const fieldError = (field: SignupField, id: string) =>
    fieldErrors[field] ? (
      <p className="acct-field-error" id={id} role="alert">
        {fieldErrors[field]}
        {field === "email" && emailTaken && (
          <button type="button" className="acct-inline-link" onClick={switchToLogin}>
            Log in instead
          </button>
        )}
      </p>
    ) : null;
  const inputClass = (field: SignupField, extra = "") => `acct-input${extra ? ` ${extra}` : ""}${fieldErrors[field] ? " is-invalid" : ""}`;

  return (
    <main className="acct-split" id="create-account" aria-labelledby="create-account-title">
      <div className="acct-form-col">
        <div className="acct-form-inner">
          <button type="button" className="acct-back" onClick={onBack}>
            ← Back to BuildFlow
          </button>
          <div className="acct-brand">
            <BuildFlowLogoMark />
            <strong>BuildFlow</strong>
          </div>
          {/* same chip the landing hero opens with, so the two pages share a rhythm */}
          <span className="acct-eyebrow">
            <span className="acct-eyebrow-dot" />
            Launching {LAUNCH_DATE_LABEL}
          </span>
          <div className="acct-head">
            <h1 id="create-account-title">
              {mode === "forgot" ? "Reset your password." : isSignup ? "Create your workspace." : "Welcome back."}
            </h1>
            <p>
              {mode === "forgot"
                ? "Enter your email and we'll send a link to choose a new one."
                : isSignup
                  ? "Coordinate crews, materials, and schedules in one place."
                  : "Sign in to your production workspace."}
            </p>
          </div>

          <form className="acct-form" onSubmit={submit}>
            {isSignup && (
              <>
                <div className="acct-field">
                  <label htmlFor="account-name">Your name</label>
                  <div className="acct-input-wrap">
                    <input
                      id="account-name"
                      className={inputClass("name")}
                      type="text"
                      value={name}
                      onChange={(event) => {
                        setName(event.target.value);
                        clearField("name");
                      }}
                      placeholder="Jordan Reyes"
                      autoComplete="name"
                      aria-invalid={fieldErrors.name ? true : undefined}
                      aria-describedby={fieldErrors.name ? "account-name-error" : undefined}
                    />
                  </div>
                  {fieldError("name", "account-name-error")}
                </div>
                <div className="acct-field">
                  <label htmlFor="account-company">Company</label>
                  <div className="acct-input-wrap">
                    <input
                      id="account-company"
                      className={inputClass("company")}
                      type="text"
                      value={company}
                      onChange={(event) => {
                        setCompany(event.target.value);
                        clearField("company");
                      }}
                      placeholder="Reyes Construction"
                      autoComplete="organization"
                      aria-invalid={fieldErrors.company ? true : undefined}
                      aria-describedby={fieldErrors.company ? "account-company-error" : "account-company-hint"}
                    />
                  </div>
                  {fieldError("company", "account-company-error") ?? (
                    <p className="acct-hint" id="account-company-hint">
                      This becomes your workspace name. You can rename it later in Settings.
                    </p>
                  )}
                </div>
              </>
            )}
            <div className="acct-field">
              <label htmlFor="account-email">{isSignup ? "Work email" : "Email"}</label>
              <div className="acct-input-wrap">
                <input
                  id="account-email"
                  className={inputClass("email")}
                  type="email"
                  value={email}
                  onChange={(event) => {
                    setEmail(event.target.value);
                    clearField("email");
                  }}
                  placeholder="name@company.com"
                  autoComplete="email"
                  aria-invalid={fieldErrors.email ? true : undefined}
                  aria-describedby={fieldErrors.email ? "account-email-error" : undefined}
                />
              </div>
              {fieldError("email", "account-email-error") ??
                (isSignup && isPersonalEmail(email) && (
                  <p className="acct-hint" id="account-email-hint">
                    That looks like a personal address. It works, but a company email keeps this workspace with the business if people
                    change.
                  </p>
                ))}
            </div>
            {mode === "forgot" && resetSent && (
              <p className="acct-success" role="status">
                If there's a BuildFlow account for <b>{email.trim()}</b>, a reset link is on its way. It works for one hour.
              </p>
            )}
            {mode !== "forgot" && (
              <div className="acct-field">
                <div className="acct-label-row">
                  <label htmlFor="account-password">Password</label>
                  {!isSignup && (
                    <button
                      type="button"
                      className="acct-link-btn"
                      onClick={() => {
                        setMode("forgot");
                        setResetSent(false);
                        setFieldErrors({});
                        setError("");
                      }}
                    >
                      Forgot password?
                    </button>
                  )}
                </div>
                <div className="acct-input-wrap">
                  <input
                    id="account-password"
                    className={inputClass("password", "has-toggle")}
                    type={showPassword ? "text" : "password"}
                    value={password}
                    onChange={(event) => {
                      setPassword(event.target.value);
                      clearField("password");
                    }}
                    placeholder={isSignup ? "At least 8 characters" : "Your password"}
                    autoComplete={isSignup ? "new-password" : "current-password"}
                    aria-invalid={fieldErrors.password ? true : undefined}
                    aria-describedby={fieldErrors.password ? "account-password-error" : isSignup ? "account-password-hint" : undefined}
                  />
                  <button
                    type="button"
                    className="acct-pw-toggle"
                    onClick={() => setShowPassword((value) => !value)}
                    aria-label={showPassword ? "Hide password" : "Show password"}
                  >
                    {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                  </button>
                </div>
                {isSignup && password.length > 0 && (
                  <div className="acct-strength" data-score={strength.score}>
                    <div className="acct-strength-bar" aria-hidden="true">
                      <span />
                      <span />
                      <span />
                      <span />
                    </div>
                    <p className="acct-strength-label" aria-live="polite">
                      <span>Password strength</span>
                      <b>{strength.label}</b>
                    </p>
                  </div>
                )}
                {fieldError("password", "account-password-error") ??
                  (isSignup && (
                    <p className="acct-hint" id="account-password-hint">
                      At least 8 characters. A longer phrase with a number or symbol is strongest. Avoid common words and your email.
                    </p>
                  ))}
              </div>
            )}
            {mode !== "forgot" && (
              <div className="acct-checks">
                {isSignup && (
                  <div className={fieldErrors.terms ? "acct-remember acct-terms is-invalid" : "acct-remember acct-terms"}>
                    <input
                      id="account-terms"
                      type="checkbox"
                      checked={acceptTerms}
                      onChange={(event) => {
                        setAcceptTerms(event.target.checked);
                        clearField("terms");
                      }}
                      aria-invalid={fieldErrors.terms ? true : undefined}
                      aria-describedby={fieldErrors.terms ? "account-terms-error" : undefined}
                    />
                    {/* the links sit outside the <label> so opening the Terms doesn't also tick the box */}
                    <span>
                      <label htmlFor="account-terms">I agree to the</label> <a href="#terms">Terms &amp; Conditions</a> and{" "}
                      <a href="#privacy">Privacy Policy</a>.
                    </span>
                  </div>
                )}
                {fieldError("terms", "account-terms-error")}
                <label className="acct-remember">
                  <input type="checkbox" checked={remember} onChange={(event) => setRemember(event.target.checked)} />
                  <span>Keep me signed in for 30 days</span>
                </label>
              </div>
            )}
            {error && (
              <p className="acct-error" id="account-error" role="alert">
                {error}
              </p>
            )}
            {!(mode === "forgot" && resetSent) && (
              <button type="submit" className="acct-primary" disabled={busy}>
                {busy
                  ? mode === "forgot"
                    ? "Sending…"
                    : isSignup
                      ? "Creating your workspace…"
                      : "Signing in…"
                  : mode === "forgot"
                    ? "Send reset link"
                    : isSignup
                      ? "Create account"
                      : "Sign in"}
              </button>
            )}
          </form>

          {mode !== "forgot" && anyProvider && (
            <>
              <div className="acct-divider">
                <span />
                <em>or continue with</em>
                <span />
              </div>
              <div
                className={oauthProviders.google && oauthProviders.microsoft ? "acct-providers" : "acct-providers acct-providers-single"}
              >
                {oauthProviders.google && (
                  <button type="button" className="acct-provider" onClick={() => startWithProvider("google")}>
                    <span className="acct-google-mark" aria-hidden="true">
                      G
                    </span>
                    Google
                  </button>
                )}
                {oauthProviders.microsoft && (
                  <button type="button" className="acct-provider" onClick={() => startWithProvider("microsoft")}>
                    <span className="acct-ms-mark" aria-hidden="true">
                      <i />
                      <i />
                      <i />
                      <i />
                    </span>
                    Microsoft
                  </button>
                )}
              </div>
            </>
          )}

          <p className="acct-toggle-copy">
            {mode === "forgot" ? "Remembered it? " : isSignup ? "Existing user? " : "New to BuildFlow? "}
            <button
              type="button"
              onClick={() => {
                setMode(mode === "login" ? "signup" : "login");
                setResetSent(false);
                setFieldErrors({});
                setError("");
              }}
            >
              {mode === "forgot" ? "Back to sign in" : isSignup ? "Log in" : "Create an account"}
            </button>
          </p>

          {!isSignup && (
            <p className="acct-legal">
              By continuing, you agree to the <a href="#terms">Terms &amp; Conditions</a> and <a href="#privacy">Privacy Policy</a>.
            </p>
          )}
        </div>
      </div>

      <aside className="acct-aside" aria-hidden="true">
        <div className="acct-aurora acct-aurora-1" />
        <div className="acct-aurora acct-aurora-2" />
        <div className="acct-aurora acct-aurora-3" />
        <div className="acct-aside-brand">
          <BuildFlowLogoMark /> BuildFlow
        </div>
        {/* signature visual: the schedule assembling itself (decorative; the whole
            aside is already aria-hidden). Pure CSS — see account-redesign.css. */}
        <AcctScheduleViz />
        <blockquote className="acct-aside-quote">
          <p className="acct-aside-type">
            <WxTypewriter
              key={mode}
              normal={isSignup ? "Where crews, projects, and schedules " : "Welcome back to your "}
              em={isSignup ? "run as one." : "command center."}
            />
          </p>
          <cite>Run the whole jobsite from one place.</cite>
        </blockquote>
      </aside>
    </main>
  );
}

function WelcomeBusinessTypePage({
  onBack,
  onContinue,
  hasWork = false
}: {
  onBack: () => void;
  onContinue: (businessType: BusinessTypeId) => void;
  /** The workspace already holds projects: nothing is seeded, the app just re-tunes. */
  hasWork?: boolean;
}) {
  const [businessType, setBusinessType] = useState<BusinessTypeId | "">("");
  const [businessTypeError, setBusinessTypeError] = useState("");
  const profile = tradeProfileFor(businessType);

  const submitBusinessType = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!isBusinessTypeId(businessType)) {
      setBusinessTypeError("Choose your trade to continue.");
      return;
    }
    setBusinessTypeError("");
    onContinue(businessType);
  };

  return (
    <main className="acct-split acct-split-wide" id="business-type" aria-labelledby="business-type-title">
      <div className="acct-form-col">
        <div className="acct-form-inner">
          <button type="button" className="acct-back" onClick={onBack}>
            ← Back to account details
          </button>
          <div className="acct-brand">
            <BuildFlowLogoMark />
            <strong>BuildFlow</strong>
          </div>
          <div className="acct-head">
            <h1 id="business-type-title">What type of Business do you own</h1>
            <p>Pick your trade — BuildFlow sets up crews, phases, readiness checks and its AI around it.</p>
          </div>

          <form className="acct-form" onSubmit={submitBusinessType}>
            {/* A radiogroup of trade cards. Each card is a real radio labelled by
                the trade name, so keyboard users and the tests both pick a trade
                the same way a pointer does. */}
            <div
              className="acct-pick-grid acct-trade-grid"
              role="radiogroup"
              aria-label="Business type"
              aria-describedby={businessTypeError ? "business-type-error" : undefined}
            >
              {businessTypeOptions.map((type, i) => {
                const trade = tradeProfiles[type];
                const Icon = TRADE_ICONS[trade.icon];
                const checked = businessType === type;
                // The radio is named by the trade alone; the tagline is its
                // description. Otherwise the accessible name would be the whole
                // card ("Asphalt Paving, milling and striping…") and a screen
                // reader would read the pitch before the choice.
                const slug = type.toLowerCase().replace(/[^a-z0-9]+/g, "-");
                const labelId = `business-type-${slug}-label`;
                const descriptionId = `business-type-${slug}-desc`;
                return (
                  <label key={type} className={checked ? "acct-pick selected" : "acct-pick"} style={{ "--i": i } as CSSProperties}>
                    <input
                      type="radio"
                      name="business-type"
                      value={type}
                      aria-labelledby={labelId}
                      aria-describedby={descriptionId}
                      checked={checked}
                      onChange={() => {
                        setBusinessType(type);
                        if (businessTypeError) setBusinessTypeError("");
                      }}
                    />
                    <span className={`acct-pick-ico tone-${trade.tone}`}>
                      <Icon size={18} />
                    </span>
                    <span className="acct-pick-copy">
                      <strong id={labelId}>{trade.label}</strong>
                      <em id={descriptionId}>{trade.tagline}</em>
                    </span>
                    <span className="acct-pick-check" aria-hidden="true">
                      <Check size={13} />
                    </span>
                  </label>
                );
              })}
            </div>
            {businessTypeError && (
              <p className="acct-error" id="business-type-error" role="alert">
                {businessTypeError}
              </p>
            )}
            <button type="submit" className="acct-primary">
              Get BuildFlow
            </button>
          </form>
        </div>
      </div>

      <aside className="acct-aside" aria-hidden="true">
        <div className="acct-aurora acct-aurora-1" />
        <div className="acct-aurora acct-aurora-2" />
        <div className="acct-aurora acct-aurora-3" />
        <div className="acct-aside-brand">
          <BuildFlowLogoMark /> BuildFlow
        </div>
        <AcctScheduleViz />
        <blockquote className="acct-aside-quote">
          <p className="acct-aside-type">
            {/* Re-keying on the trade replays the typewriter, so the panel answers the
                selection with the same phrasing the dashboard uses for the profile. */}
            <WxTypewriter
              key={businessType || "empty"}
              normal={businessType ? "Production scheduling tuned for " : "Production scheduling for "}
              em={businessType ? `${businessType.toLowerCase()} crews.` : "every trade."}
            />
          </p>
          <cite>Run the whole jobsite from one place.</cite>
        </blockquote>
        {/* What the workspace will actually contain for the chosen trade. Keyed on
            the trade so the rows replay their rise on every change. */}
        <dl className="acct-preview" key={businessType || "empty"}>
          <dt className="acct-preview-title">{hasWork ? "What changes for your workspace" : "Your workspace will include"}</dt>
          {profile ? (
            <>
              <p className="acct-preview-desc">{profile.description}</p>
              {hasWork && (
                <p className="acct-preview-desc acct-preview-note">
                  Your existing projects, crews and schedule stay exactly as they are. BuildFlow re-tunes its phases, readiness checks,
                  DelayIQ categories and AI around {profile.label.toLowerCase()} work.
                </p>
              )}
              {(
                [
                  ["Crews", profile.crewTypes],
                  ["Phases", profile.phases],
                  ["Readiness checks", profile.readinessChecks.slice(0, 4)],
                  ["DelayIQ categories", profile.delayIQCategories.slice(0, 4)]
                ] as Array<[string, string[]]>
              ).map(([title, items], i) => (
                <div className="acct-preview-row" key={title} style={{ "--i": i } as CSSProperties}>
                  <dt>{title}</dt>
                  <dd>
                    {items.map((item) => (
                      <span className="acct-preview-chip" key={item}>
                        {item}
                      </span>
                    ))}
                  </dd>
                </div>
              ))}
            </>
          ) : (
            <p className="acct-preview-empty">
              Choose a trade and BuildFlow shapes its crews, production phases, readiness checks, delayIQ categories and AI around how that
              business actually runs.
            </p>
          )}
        </dl>
      </aside>
    </main>
  );
}

function WelcomeAdditionalProductsPage({
  businessType,
  onBack,
  onContinue
}: {
  businessType: BusinessTypeId | "";
  onBack: () => void;
  onContinue: (selectedPlan: ProductPlanId, selectedProducts: OnboardingProductId[], seats: number) => Promise<void> | void;
}) {
  const [selectedPlan, setSelectedPlan] = useState<ProductPlanId | "">(readStoredPlan);
  const [selectedProducts, setSelectedProducts] = useState<OnboardingProductId[]>(readStoredProducts);
  const [seats, setSeats] = useState(DEFAULT_SEATS);
  const [productError, setProductError] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  // Add-ons are optional — the base product is a complete purchase on its own.
  const canContinue = Boolean(selectedPlan);
  const plan = selectedPlan ? planById[selectedPlan] : undefined;
  const monthlyTotal = plan && typeof plan.priceMonthly === "number" ? plan.priceMonthly * seats : null;

  const toggleProduct = (productId: OnboardingProductId) => {
    setSelectedProducts((current) =>
      current.includes(productId) ? current.filter((item) => item !== productId) : [...current, productId]
    );
    if (productError) setProductError("");
  };

  const submitProducts = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!isProductPlanId(selectedPlan)) {
      setProductError("Choose a BuildFlow plan to continue.");
      return;
    }

    setProductError("");
    setIsSubmitting(true);
    try {
      await onContinue(selectedPlan, selectedProducts, seats);
    } catch (error) {
      setProductError(error instanceof Error ? error.message : "Unable to finish onboarding. Try again.");
      setIsSubmitting(false);
    }
  };

  return (
    <main className="acct-split acct-split-wide" id="additional-products" aria-labelledby="additional-products-title">
      <div className="acct-form-col">
        <div className="acct-form-inner">
          <button type="button" className="acct-back" onClick={onBack}>
            ← Back to business type
          </button>
          <div className="acct-brand">
            <BuildFlowLogoMark />
            <strong>BuildFlow</strong>
          </div>

          <span className="acct-eyebrow">
            <span className="acct-eyebrow-dot" />
            Set up your workspace
          </span>

          <div className="acct-head">
            <h1 id="additional-products-title">What additional products do you want to use?</h1>
            <p>{businessType ? `BuildFlow for ${businessType}` : "Choose your BuildFlow setup"}</p>
          </div>

          <form className="acct-form" onSubmit={submitProducts}>
            <section className="acct-sec" aria-labelledby="additional-products-products-title">
              <div className="acct-sec-head">
                <h2 id="additional-products-products-title">Additional products</h2>
                <span>Choose one or more</span>
              </div>
              <div className="acct-pick-grid">
                {onboardingProductOptions.map((product, i) => {
                  const program = programRegistry[product.id];
                  const Icon = program.icon;
                  const checked = selectedProducts.includes(product.id);
                  return (
                    <label key={product.id} className={checked ? "acct-pick selected" : "acct-pick"} style={{ "--i": i } as CSSProperties}>
                      <input type="checkbox" checked={checked} onChange={() => toggleProduct(product.id)} />
                      <span className={`acct-pick-ico tone-${program.tone}`}>
                        <Icon size={18} />
                      </span>
                      <span className="acct-pick-copy">
                        <strong>{product.label}</strong>
                        <em>{product.description}</em>
                      </span>
                      <span className="acct-pick-check" aria-hidden="true">
                        <Check size={13} />
                      </span>
                    </label>
                  );
                })}
              </div>
            </section>

            <section className="acct-sec" aria-labelledby="additional-products-plan-title">
              <div className="acct-sec-head">
                <h2 id="additional-products-plan-title">What type of plan?</h2>
                <span>Choose one</span>
              </div>
              <div className="acct-plan-grid" role="radiogroup" aria-label="BuildFlow plan">
                {productPlans.map((plan, i) => (
                  <button
                    key={plan.id}
                    type="button"
                    className={selectedPlan === plan.id ? "acct-plan selected" : "acct-plan"}
                    aria-pressed={selectedPlan === plan.id}
                    aria-label={`Select ${plan.name} plan`}
                    style={{ "--i": i } as CSSProperties}
                    onClick={() => {
                      setSelectedPlan(plan.id);
                      if (productError) setProductError("");
                    }}
                  >
                    <span className="acct-plan-check" aria-hidden="true">
                      <Check size={12} />
                    </span>
                    <strong>{plan.name}</strong>
                    <span className="acct-plan-price">{plan.price}</span>
                    <em>{plan.priceNote}</em>
                  </button>
                ))}
              </div>
            </section>

            <section className="acct-sec" aria-labelledby="additional-products-seats-title">
              <div className="acct-sec-head">
                <h2 id="additional-products-seats-title">How many people will use BuildFlow?</h2>
                <span>Every plan is priced per seat</span>
              </div>
              <div className="acct-seats">
                <div className="acct-field acct-seats-field">
                  <label htmlFor="additional-products-seats">Seats</label>
                  <div className="acct-input-wrap">
                    <input
                      id="additional-products-seats"
                      className="acct-input"
                      type="number"
                      inputMode="numeric"
                      min={1}
                      max={1000}
                      step={1}
                      value={seats}
                      onChange={(event) => setSeats(Math.min(1000, Math.max(1, Math.round(Number(event.target.value) || 1))))}
                    />
                  </div>
                </div>
                <p className="acct-seats-total" aria-live="polite">
                  {!plan ? (
                    <span>Pick a plan to see your monthly total.</span>
                  ) : monthlyTotal === 0 ? (
                    <span>
                      <b>$0 / month</b> — Free for the whole team.
                    </span>
                  ) : monthlyTotal != null ? (
                    <span>
                      <b>${monthlyTotal.toLocaleString("en-US")} / month</b> for {seats} {seats === 1 ? "seat" : "seats"} on {plan.name}.
                      Starts with a 14-day trial; nothing is charged today.
                    </span>
                  ) : (
                    <span>
                      <b>Custom pricing</b> — sales will size Enterprise for {seats} {seats === 1 ? "seat" : "seats"}.
                    </span>
                  )}
                </p>
              </div>
            </section>

            {productError && (
              <p className="acct-error" id="additional-products-error" role="alert">
                {productError}
              </p>
            )}

            <button type="submit" className="acct-primary" disabled={!canContinue || isSubmitting}>
              {isSubmitting ? "Building workspace..." : selectedProducts.length > 0 ? "Continue to BuildFlow" : "Continue without add-ons"}
              {!isSubmitting && <ArrowRight size={18} />}
            </button>
            <p className="acct-hint acct-hint-center">Add-ons are optional. You can turn any of them on later in Settings.</p>
          </form>
        </div>
      </div>

      <aside className="acct-aside" aria-hidden="true">
        <div className="acct-aurora acct-aurora-1" />
        <div className="acct-aurora acct-aurora-2" />
        <div className="acct-aurora acct-aurora-3" />
        <div className="acct-aside-brand">
          <BuildFlowLogoMark /> BuildFlow
        </div>
        <AcctScheduleViz />
        <blockquote className="acct-aside-quote">
          <p className="acct-aside-type">
            <WxTypewriter normal="Pick the tools your " em="crews run on." />
          </p>
          <cite>Run the whole jobsite from one place.</cite>
        </blockquote>
      </aside>
    </main>
  );
}

/** The token an emailed link carries after "?" inside the hash: "#reset-password?token=…". */
function tokenFromHash(): string {
  if (typeof window === "undefined") return "";
  const query = window.location.hash.split("?")[1] ?? "";
  return new URLSearchParams(query).get("token") ?? "";
}

/** Landing page for the emailed reset link: one new password, then straight into the workspace. */
function WelcomeResetPasswordPage({
  onBack,
  onReset
}: {
  onBack: () => void;
  onReset: (token: string, password: string) => Promise<void>;
}) {
  const [token, setToken] = useState(tokenFromHash);
  const [password, setPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);
  const strength = passwordStrength(password);
  const invalidLink = !token;

  const submit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (busy) return;
    const problem = passwordProblem(password);
    if (problem) {
      setError(problem);
      return;
    }
    setError("");
    setBusy(true);
    try {
      await onReset(token, password);
    } catch (err) {
      // a weak password hands back a fresh token so the second try still works
      if (err instanceof ApiError && err.code === "weak_password") {
        const fresh = (err as ApiError & { token?: string }).token;
        if (fresh) setToken(fresh);
      }
      setError(err instanceof Error ? err.message : "Something went wrong. Please try again.");
      setBusy(false);
    }
  };

  return (
    <main className="acct-split" id="reset-password" aria-labelledby="reset-password-title">
      <div className="acct-form-col">
        <div className="acct-form-inner">
          <button type="button" className="acct-back" onClick={onBack}>
            ← Back to sign in
          </button>
          <div className="acct-brand">
            <BuildFlowLogoMark />
            <strong>BuildFlow</strong>
          </div>
          <div className="acct-head">
            <h1 id="reset-password-title">Choose a new password.</h1>
            <p>
              {invalidLink ? "This link is missing its token." : "You'll be signed in as soon as it's saved. Other devices are signed out."}
            </p>
          </div>
          {invalidLink ? (
            <p className="acct-error" role="alert">
              Open the link from the email we sent, or{" "}
              <button type="button" className="acct-inline-link" onClick={onBack}>
                request a new one
              </button>
              .
            </p>
          ) : (
            <form className="acct-form" onSubmit={submit}>
              <div className="acct-field">
                <label htmlFor="reset-password-input">New password</label>
                <div className="acct-input-wrap">
                  <input
                    id="reset-password-input"
                    className={error ? "acct-input has-toggle is-invalid" : "acct-input has-toggle"}
                    type={showPassword ? "text" : "password"}
                    value={password}
                    onChange={(event) => {
                      setPassword(event.target.value);
                      if (error) setError("");
                    }}
                    placeholder="At least 8 characters"
                    autoComplete="new-password"
                    autoFocus
                    aria-invalid={error ? true : undefined}
                    aria-describedby={error ? "reset-password-error" : "reset-password-hint"}
                  />
                  <button
                    type="button"
                    className="acct-pw-toggle"
                    onClick={() => setShowPassword((value) => !value)}
                    aria-label={showPassword ? "Hide password" : "Show password"}
                  >
                    {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                  </button>
                </div>
                {password.length > 0 && (
                  <div className="acct-strength" data-score={strength.score}>
                    <div className="acct-strength-bar" aria-hidden="true">
                      <span />
                      <span />
                      <span />
                      <span />
                    </div>
                    <p className="acct-strength-label" aria-live="polite">
                      <span>Password strength</span>
                      <b>{strength.label}</b>
                    </p>
                  </div>
                )}
                {error ? (
                  <p className="acct-field-error" id="reset-password-error" role="alert">
                    {error}
                  </p>
                ) : (
                  <p className="acct-hint" id="reset-password-hint">
                    At least 8 characters. A longer phrase with a number or symbol is strongest. Avoid common words and your email.
                  </p>
                )}
              </div>
              <button type="submit" className="acct-primary" disabled={busy}>
                {busy ? "Saving…" : "Save password and sign in"}
              </button>
            </form>
          )}
        </div>
      </div>
      <aside className="acct-aside" aria-hidden="true">
        <div className="acct-aurora acct-aurora-1" />
        <div className="acct-aurora acct-aurora-2" />
        <div className="acct-aurora acct-aurora-3" />
        <div className="acct-aside-brand">
          <BuildFlowLogoMark /> BuildFlow
        </div>
        <AcctScheduleViz />
        <blockquote className="acct-aside-quote">
          <p className="acct-aside-type">
            <WxTypewriter normal="Back on the " em="schedule in a minute." />
          </p>
          <cite>Run the whole jobsite from one place.</cite>
        </blockquote>
      </aside>
    </main>
  );
}

/** Landing page for the emailed confirmation link. Confirms on arrival, then offers the way in. */
function WelcomeVerifyEmailPage({ onContinue, onLogin }: { onContinue: () => Promise<boolean>; onLogin: () => void }) {
  const [state, setState] = useState<"checking" | "verified" | "failed">(() => (tokenFromHash() ? "checking" : "failed"));
  const [message, setMessage] = useState("");
  const [busy, setBusy] = useState(false);

  useEffect(() => {
    const token = tokenFromHash();
    if (!token) return;
    let cancelled = false;
    apiVerifyEmail(token)
      .then(() => {
        if (!cancelled) setState("verified");
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        setMessage(err instanceof Error ? err.message : "This confirmation link is invalid or has expired.");
        setState("failed");
      });
    return () => {
      cancelled = true;
    };
  }, []);

  const proceed = async () => {
    setBusy(true);
    const entered = await onContinue().catch(() => false);
    if (!entered) {
      setBusy(false);
      onLogin();
    }
  };

  return (
    <main className="acct-split" id="verify-email" aria-labelledby="verify-email-title">
      <div className="acct-form-col">
        <div className="acct-form-inner">
          <div className="acct-brand">
            <BuildFlowLogoMark />
            <strong>BuildFlow</strong>
          </div>
          <div className="acct-head">
            <h1 id="verify-email-title">
              {state === "checking" ? "Confirming your email…" : state === "verified" ? "Email confirmed." : "That link didn't work."}
            </h1>
            <p>
              {state === "checking"
                ? "One moment."
                : state === "verified"
                  ? "Inviting your team and managing billing are unlocked for this workspace."
                  : message || "Open the newest confirmation email, or request another one from your workspace."}
            </p>
          </div>
          {state !== "checking" && (
            <button type="button" className="acct-primary" onClick={proceed} disabled={busy}>
              {busy ? "Opening…" : state === "verified" ? "Continue to BuildFlow" : "Sign in"}
            </button>
          )}
        </div>
      </div>
      <aside className="acct-aside" aria-hidden="true">
        <div className="acct-aurora acct-aurora-1" />
        <div className="acct-aurora acct-aurora-2" />
        <div className="acct-aurora acct-aurora-3" />
        <div className="acct-aside-brand">
          <BuildFlowLogoMark /> BuildFlow
        </div>
        <AcctScheduleViz />
        <blockquote className="acct-aside-quote">
          <p className="acct-aside-type">
            <WxTypewriter normal="One address, " em="one workspace." />
          </p>
          <cite>Run the whole jobsite from one place.</cite>
        </blockquote>
      </aside>
    </main>
  );
}

/** Top-bar form of the notice: one small pill that resends the confirmation link in place. */
function VerifyEmailBadge({ email }: { email: string }) {
  const [state, setState] = useState<"idle" | "sending" | "sent" | "failed">("idle");
  const resend = async () => {
    setState("sending");
    try {
      await apiRequestEmailVerification();
      setState("sent");
    } catch {
      setState("failed");
    }
  };
  return (
    <button
      type="button"
      className={`topbar-verify${state === "sent" ? " is-sent" : ""}`}
      onClick={resend}
      disabled={state === "sending" || state === "sent"}
      title={`Confirm ${email} to unlock team invites and billing`}
      aria-label={state === "sent" ? "Confirmation email sent" : `Confirm ${email}: resend the confirmation email`}
    >
      <MailCheck size={14} aria-hidden="true" />
      {state === "sent" ? "Sent" : state === "sending" ? "Sending…" : state === "failed" ? "Try again" : "Confirm email"}
    </button>
  );
}
const TEAM_ROLE_OPTIONS: UserRole[] = ["Project Manager", "Superintendent", "Crew Lead"];

/** One editable invite row: email + role. Shared by the onboarding step and Settings. */
function InviteRows({
  rows,
  onChange,
  errors
}: {
  rows: InviteDraft[];
  onChange: (rows: InviteDraft[]) => void;
  errors?: Record<number, string>;
}) {
  const update = (index: number, patch: Partial<InviteDraft>) => onChange(rows.map((row, i) => (i === index ? { ...row, ...patch } : row)));
  return (
    <div className="acct-invite-rows">
      {rows.map((row, index) => (
        <div className="acct-invite-row" key={index}>
          <div className="acct-field">
            <label htmlFor={`invite-email-${index}`} className="acct-sr-only">
              Email {index + 1}
            </label>
            <div className="acct-input-wrap">
              <input
                id={`invite-email-${index}`}
                className={errors?.[index] ? "acct-input is-invalid" : "acct-input"}
                type="email"
                value={row.email}
                placeholder="teammate@company.com"
                autoComplete="off"
                onChange={(event) => update(index, { email: event.target.value })}
                aria-invalid={errors?.[index] ? true : undefined}
              />
            </div>
            {errors?.[index] && <p className="acct-field-error">{errors[index]}</p>}
          </div>
          <div className="acct-field">
            <label htmlFor={`invite-role-${index}`} className="acct-sr-only">
              Role {index + 1}
            </label>
            <select
              id={`invite-role-${index}`}
              className="acct-input acct-select"
              value={row.role}
              onChange={(event) => update(index, { role: event.target.value as UserRole })}
            >
              {TEAM_ROLE_OPTIONS.map((role) => (
                <option key={role} value={role}>
                  {role}
                </option>
              ))}
            </select>
          </div>
          {rows.length > 1 && (
            <button
              type="button"
              className="acct-invite-remove"
              aria-label={`Remove row ${index + 1}`}
              onClick={() => onChange(rows.filter((_, i) => i !== index))}
            >
              <X size={16} />
            </button>
          )}
        </div>
      ))}
      {rows.length < 20 && (
        <button
          type="button"
          className="acct-link-btn acct-invite-add"
          onClick={() => onChange([...rows, { email: "", role: "Crew Lead" }])}
        >
          + Add another
        </button>
      )}
    </div>
  );
}

/** Validates drafts; blank rows are dropped, bad emails are named. */
function checkInviteRows(rows: InviteDraft[]): { valid: InviteDraft[]; errors: Record<number, string> } {
  const errors: Record<number, string> = {};
  const valid: InviteDraft[] = [];
  const seen = new Set<string>();
  rows.forEach((row, index) => {
    const email = row.email.trim().toLowerCase();
    if (!email) return;
    if (!EMAIL_PATTERN.test(email)) {
      errors[index] = "Enter a valid email address.";
      return;
    }
    if (seen.has(email)) {
      errors[index] = "Already in the list.";
      return;
    }
    seen.add(email);
    valid.push({ email, role: row.role });
  });
  return { valid, errors };
}

/** Last onboarding step: who else should be in the workspace. Skippable — invites also live in Settings. */
function WelcomeInviteTeamPage({ onDone }: { onDone: () => void }) {
  const [rows, setRows] = useState<InviteDraft[]>([
    { email: "", role: "Superintendent" },
    { email: "", role: "Crew Lead" },
    { email: "", role: "Crew Lead" }
  ]);
  const [errors, setErrors] = useState<Record<number, string>>({});
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [results, setResults] = useState<InviteResult[] | null>(null);

  const submit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (busy) return;
    const { valid, errors: problems } = checkInviteRows(rows);
    setErrors(problems);
    if (Object.keys(problems).length > 0) return;
    if (valid.length === 0) {
      onDone();
      return;
    }
    setBusy(true);
    setError("");
    try {
      const response = await apiSendInvites(valid);
      track(EVENTS.invitesSent, {
        count: valid.length,
        held: response.results.filter((r) => r.status === "held").length,
        source: "onboarding"
      });
      setResults(response.results);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Something went wrong. Please try again.");
    } finally {
      setBusy(false);
    }
  };

  const held = results?.some((result) => result.status === "held");

  return (
    <main className="acct-split acct-split-wide" id="invite-team" aria-labelledby="invite-team-title">
      <div className="acct-form-col">
        <div className="acct-form-inner">
          <div className="acct-brand">
            <BuildFlowLogoMark />
            <strong>BuildFlow</strong>
          </div>
          <span className="acct-eyebrow">
            <span className="acct-eyebrow-dot" />
            Last step
          </span>
          <div className="acct-head">
            <h1 id="invite-team-title">Who runs the work with you?</h1>
            <p>
              Invite your supers and crew leads now, or later from Settings. They get an email with a link that puts them straight into this
              workspace.
            </p>
          </div>
          {results ? (
            <div className="acct-form">
              <ul className="acct-invite-results">
                {results.map((result) => (
                  <li key={result.email} data-status={result.status}>
                    <strong>{result.email}</strong>
                    <span>
                      {result.status === "sent"
                        ? "Invite sent"
                        : result.status === "held"
                          ? "Will send once you confirm your email"
                          : (result.reason ?? "Skipped")}
                    </span>
                  </li>
                ))}
              </ul>
              {held && (
                <p className="acct-hint">
                  We emailed you a confirmation link at signup. Open it and the held invites go out automatically.
                </p>
              )}
              <button type="button" className="acct-primary" onClick={onDone}>
                Open BuildFlow
                <ArrowRight size={18} />
              </button>
            </div>
          ) : (
            <form className="acct-form" onSubmit={submit}>
              <InviteRows rows={rows} onChange={setRows} errors={errors} />
              {error && (
                <p className="acct-error" role="alert">
                  {error}
                </p>
              )}
              <button type="submit" className="acct-primary" disabled={busy}>
                {busy ? "Sending…" : rows.some((row) => row.email.trim()) ? "Send invites" : "Skip for now"}
                {!busy && <ArrowRight size={18} />}
              </button>
              {rows.some((row) => row.email.trim()) && (
                <button type="button" className="acct-link-btn acct-hint-center" onClick={onDone}>
                  Skip for now
                </button>
              )}
            </form>
          )}
        </div>
      </div>
      <aside className="acct-aside" aria-hidden="true">
        <div className="acct-aurora acct-aurora-1" />
        <div className="acct-aurora acct-aurora-2" />
        <div className="acct-aurora acct-aurora-3" />
        <div className="acct-aside-brand">
          <BuildFlowLogoMark /> BuildFlow
        </div>
        <AcctScheduleViz />
        <blockquote className="acct-aside-quote">
          <p className="acct-aside-type">
            <WxTypewriter normal="The whole crew, " em="one schedule." />
          </p>
          <cite>Run the whole jobsite from one place.</cite>
        </blockquote>
      </aside>
    </main>
  );
}

/** Landing page for an emailed invite: see who invited you, set a password, you're in. */
function WelcomeAcceptInvitePage({
  onAccept,
  onLogin
}: {
  onAccept: (input: { token: string; name: string; password: string; acceptTerms: true; remember?: boolean }) => Promise<void>;
  onLogin: () => void;
}) {
  const token = tokenFromHash();
  const [preview, setPreview] = useState<InvitePreview | null>(null);
  const [previewError, setPreviewError] = useState("");
  const [name, setName] = useState("");
  const [password, setPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [acceptTerms, setAcceptTerms] = useState(false);
  const [fieldErrors, setFieldErrors] = useState<Partial<Record<"name" | "password" | "terms", string>>>({});
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);
  const strength = passwordStrength(password, preview?.email ?? "");

  useEffect(() => {
    if (!token) {
      setPreviewError("This invite link is missing its token.");
      return;
    }
    let cancelled = false;
    apiFetchInvitePreview(token)
      .then((data) => {
        if (!cancelled) setPreview(data);
      })
      .catch((err: unknown) => {
        if (!cancelled) setPreviewError(err instanceof Error ? err.message : "This invite is invalid or has expired.");
      });
    return () => {
      cancelled = true;
    };
  }, [token]);

  const submit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (busy) return;
    const problems: typeof fieldErrors = {};
    if (!name.trim()) problems.name = "Enter your name.";
    const weak = passwordProblem(password, preview?.email ?? "");
    if (weak) problems.password = weak;
    if (!acceptTerms) problems.terms = "Please agree to the Terms & Conditions and Privacy Policy.";
    setFieldErrors(problems);
    if (Object.keys(problems).length > 0) return;
    setBusy(true);
    setError("");
    try {
      await onAccept({ token, name: name.trim(), password, acceptTerms: true, remember: true });
    } catch (err) {
      const message = err instanceof Error ? err.message : "Something went wrong. Please try again.";
      if (err instanceof ApiError && err.field === "password") setFieldErrors({ password: message });
      else setError(message);
      setBusy(false);
    }
  };

  return (
    <main className="acct-split" id="accept-invite" aria-labelledby="accept-invite-title">
      <div className="acct-form-col">
        <div className="acct-form-inner">
          <div className="acct-brand">
            <BuildFlowLogoMark />
            <strong>BuildFlow</strong>
          </div>
          <div className="acct-head">
            <h1 id="accept-invite-title">
              {previewError ? "This invite didn't work." : preview ? `Join ${preview.orgName}.` : "Checking your invite…"}
            </h1>
            <p>
              {previewError
                ? previewError
                : preview
                  ? `${preview.inviterName} invited you as a ${preview.role}. Set a password for ${preview.email} and you're in.`
                  : "One moment."}
            </p>
          </div>
          {previewError ? (
            <button type="button" className="acct-primary" onClick={onLogin}>
              Sign in instead
            </button>
          ) : preview ? (
            <form className="acct-form" onSubmit={submit}>
              <div className="acct-field">
                <label htmlFor="invite-name">Your name</label>
                <div className="acct-input-wrap">
                  <input
                    id="invite-name"
                    className={fieldErrors.name ? "acct-input is-invalid" : "acct-input"}
                    type="text"
                    value={name}
                    onChange={(event) => {
                      setName(event.target.value);
                      setFieldErrors((current) => ({ ...current, name: undefined }));
                    }}
                    placeholder="Sam Ortiz"
                    autoComplete="name"
                    autoFocus
                    aria-invalid={fieldErrors.name ? true : undefined}
                  />
                </div>
                {fieldErrors.name && (
                  <p className="acct-field-error" role="alert">
                    {fieldErrors.name}
                  </p>
                )}
              </div>
              <div className="acct-field">
                <label htmlFor="invite-email">Email</label>
                <div className="acct-input-wrap">
                  <input id="invite-email" className="acct-input" type="email" value={preview.email} readOnly aria-readonly="true" />
                </div>
                <p className="acct-hint">This is the address the invite was sent to. It's already confirmed.</p>
              </div>
              <div className="acct-field">
                <label htmlFor="invite-password">Password</label>
                <div className="acct-input-wrap">
                  <input
                    id="invite-password"
                    className={fieldErrors.password ? "acct-input has-toggle is-invalid" : "acct-input has-toggle"}
                    type={showPassword ? "text" : "password"}
                    value={password}
                    onChange={(event) => {
                      setPassword(event.target.value);
                      setFieldErrors((current) => ({ ...current, password: undefined }));
                    }}
                    placeholder="At least 8 characters"
                    autoComplete="new-password"
                    aria-invalid={fieldErrors.password ? true : undefined}
                  />
                  <button
                    type="button"
                    className="acct-pw-toggle"
                    onClick={() => setShowPassword((value) => !value)}
                    aria-label={showPassword ? "Hide password" : "Show password"}
                  >
                    {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                  </button>
                </div>
                {password.length > 0 && (
                  <div className="acct-strength" data-score={strength.score}>
                    <div className="acct-strength-bar" aria-hidden="true">
                      <span />
                      <span />
                      <span />
                      <span />
                    </div>
                    <p className="acct-strength-label" aria-live="polite">
                      <span>Password strength</span>
                      <b>{strength.label}</b>
                    </p>
                  </div>
                )}
                {fieldErrors.password && (
                  <p className="acct-field-error" role="alert">
                    {fieldErrors.password}
                  </p>
                )}
              </div>
              <div className="acct-checks">
                <div className={fieldErrors.terms ? "acct-remember acct-terms is-invalid" : "acct-remember acct-terms"}>
                  <input
                    id="invite-terms"
                    type="checkbox"
                    checked={acceptTerms}
                    onChange={(event) => {
                      setAcceptTerms(event.target.checked);
                      setFieldErrors((current) => ({ ...current, terms: undefined }));
                    }}
                  />
                  <span>
                    <label htmlFor="invite-terms">I agree to the</label> <a href="#terms">Terms &amp; Conditions</a> and{" "}
                    <a href="#privacy">Privacy Policy</a>.
                  </span>
                </div>
                {fieldErrors.terms && (
                  <p className="acct-field-error" role="alert">
                    {fieldErrors.terms}
                  </p>
                )}
              </div>
              {error && (
                <p className="acct-error" role="alert">
                  {error}
                </p>
              )}
              <button type="submit" className="acct-primary" disabled={busy}>
                {busy ? "Joining…" : `Join ${preview.orgName}`}
              </button>
            </form>
          ) : null}
        </div>
      </div>
      <aside className="acct-aside" aria-hidden="true">
        <div className="acct-aurora acct-aurora-1" />
        <div className="acct-aurora acct-aurora-2" />
        <div className="acct-aurora acct-aurora-3" />
        <div className="acct-aside-brand">
          <BuildFlowLogoMark /> BuildFlow
        </div>
        <AcctScheduleViz />
        <blockquote className="acct-aside-quote">
          <p className="acct-aside-type">
            <WxTypewriter normal="Your crew is " em="already on the board." />
          </p>
          <cite>Run the whole jobsite from one place.</cite>
        </blockquote>
      </aside>
    </main>
  );
}

const automationParticles = Array.from({ length: 30 }, (_, i) => ({
  x: (i * 37) % 100,
  delayIQ: ((i * 17) % 50) / 10,
  dur: 4 + ((i * 11) % 45) / 10,
  size: 2 + (i % 3),
  drift: (i % 2 === 0 ? 1 : -1) * (6 + (i % 4) * 4)
}));

type AutomationTone = "clear" | "rain" | "wind" | "storm";

type AutomationBoardMock = {
  kind: "board";
  bar: string;
  cols: Array<{ label: string; tone: AutomationTone }>;
};

type AutomationListMock = {
  kind: "list";
  bar: string;
  rows: Array<{ label: string; flag: string; tone: AutomationTone }>;
};

type AutomationShowcase = {
  title: string;
  text: string;
  tone: "blue" | "lavender";
  mock: AutomationBoardMock | AutomationListMock;
};

type AutomationConfig = {
  id: string;
  eyebrow: string;
  heroTitle: string;
  heroSub: string;
  glow: string;
  cardIcon: typeof Grid2X2;
  cardTitle: string;
  cardSubject: string;
  cardRows: Array<{ a: string; b: string; c: string; tone: AutomationTone }>;
  showcaseHead: string;
  showcaseTitle: string;
  showcase: [AutomationShowcase, AutomationShowcase];
  featuresTitle: string;
  features: Array<{ title: string; text: string; icon: typeof Grid2X2 }>;
  consoleTitle: string;
  consoleLines: Array<{ tag: string; text: string; ok?: boolean }>;
  stepsTitle: string;
  steps: Array<{ title: string; text: string }>;
  quote: string;
  quoteName: string;
  quoteOrg: string;
  ctaTitle: string;
  ctaText: string;
};

