type CsCell = { t?: string; c?: string; drop?: boolean; ghost?: boolean } | null;
type CsRow = { crew: string; dot: string; days: CsCell[] };

function CsBoard({ title, rows }: { title: string; rows: CsRow[] }) {
  return (
    <div className="cs-mock" aria-hidden="true">
      <div className="cs-mock-bar">
        <i />
        <i />
        <i />
        <strong>{title}</strong>
      </div>
      <div className="cs-mock-body">
        <div className="cs-board">
          <div className="cs-board-head">
            <span>Crew</span>
            <span>Mon</span>
            <span>Tue</span>
            <span>Wed</span>
            <span>Thu</span>
            <span>Fri</span>
          </div>
          {rows.map((row) => (
            <div className="cs-board-row" key={row.crew}>
              <span className="cs-crew">
                <i style={{ background: row.dot }} /> {row.crew}
              </span>
              {row.days.map((cell, ci) => {
                if (!cell) return <span key={ci} className="cs-cell" />;
                if (cell.drop) return <span key={ci} className="cs-cell drop" />;
                if (cell.ghost)
                  return (
                    <span key={ci} className="cs-chip ghost">
                      {cell.t}
                    </span>
                  );
                return (
                  <span key={ci} className={`cs-chip ${cell.c ?? "blue"}`}>
                    {cell.t}
                  </span>
                );
              })}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

/**
 * Crew Scheduling product page — media manifest.
 *
 * Every visual slot on the page is listed here. Put files in client/public and
 * fill in `src` (video) + `poster` (first frame); a slot without `src` renders
 * its built-in mock instead, so nothing on the page is ever an empty box.
 * Videos play muted/inline/looped and only while on screen.
 */
type CrewMediaSlot = "hero" | "board" | "capacity" | "conflicts" | "trades" | "ready" | "why-1" | "why-2" | "why-3" | "demo" | "reason-1" | "reason-2" | "reason-3" | "reason-4" | "reason-5" | "reason-6" | "reason-7";
type CrewMediaEntry = {
  /** Aspect ratio of the file — the slot reserves this box so the page never shifts while it loads. */
  aspect: "16:9" | "4:3" | "1:1";
  /** What belongs in the slot (for whoever produces the footage). */
  note: string;
  /** Accessible description of the visual. */
  alt: string;
  /** e.g. "/crew-hero.mp4" — served from client/public. */
  src?: string;
  /** e.g. "/crew-hero.jpg" — shown until the video plays. */
  poster?: string;
};
