type TemplateCategory = "Projects" | "Scheduling" | "Field & Ops" | "Reporting";
type TemplateItem = { name: string; category: TemplateCategory; meta: string; icon: typeof Building2; desc: string };

const scheduleTemplates: TemplateItem[] = [
  {
    name: "Commercial Concrete Pour",
    category: "Projects",
    meta: "6 phases",
    icon: Building2,
    desc: "A multi-day pour sequenced with rebar, forms, inspections, and cure windows built in."
  },
  {
    name: "Site Development & Grading",
    category: "Projects",
    meta: "8 jobs",
    icon: Truck,
    desc: "Earthwork, utilities, and grading staged with locates and weather holds accounted for."
  },
  {
    name: "Roofing Project",
    category: "Projects",
    meta: "5 phases",
    icon: Layers,
    desc: "Tear-off through membrane and flashing, staged by crew and weather risk."
  },
  {
    name: "Weekly Crew Schedule",
    category: "Scheduling",
    meta: "per week",
    icon: CalendarDays,
    desc: "Assign every crew across the week by capacity and readiness in minutes."
  },
  {
    name: "Multi-Project Dispatch",
    category: "Scheduling",
    meta: "multi-site",
    icon: Route,
    desc: "Coordinate crews and trucks across concurrent sites by location and travel time."
  },
  {
    name: "Equipment Maintenance Rotation",
    category: "Field & Ops",
    meta: "recurring",
    icon: Wrench,
    desc: "A preventive-maintenance cadence so machines never block a dispatch."
  },
  {
    name: "Materials Readiness Checklist",
    category: "Field & Ops",
    meta: "per job",
    icon: PackageCheck,
    desc: "Deliveries, permits, and locates tracked so crews only roll to work that can start."
  },
  {
    name: "Production Report Pack",
    category: "Reporting",
    meta: "CSV / PDF",
    icon: LineChart,
    desc: "Weekly production, delayIQs, and utilization — ready to export for the owner."
  }
];
const templateCategories: Array<TemplateCategory | "All"> = ["All", "Projects", "Scheduling", "Field & Ops", "Reporting"];

function WelcomeTemplatesPage({
  onBack,
  onGetStarted,
  onContactSales
}: {
  onBack: () => void;
  onGetStarted: () => void;
  onContactSales: () => void;
}) {
  const rootRef = useRef<HTMLElement>(null);
  const [category, setCategory] = useState<TemplateCategory | "All">("All");

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    let raf = 0;
    const handleMove = (event: PointerEvent) => {
      cancelAnimationFrame(raf);
      raf = requestAnimationFrame(() => {
        const nx = event.clientX / window.innerWidth;
        const ny = event.clientY / window.innerHeight;
        root.style.setProperty("--mx", `${event.clientX}px`);
        root.style.setProperty("--my", `${event.clientY}px`);
        root.style.setProperty("--px", `${(nx - 0.5) * 2}`);
        root.style.setProperty("--py", `${(ny - 0.5) * 2}`);
      });
    };
    window.addEventListener("pointermove", handleMove);
    return () => {
      window.removeEventListener("pointermove", handleMove);
      cancelAnimationFrame(raf);
    };
  }, []);

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    const targets = root.querySelectorAll("[data-reveal]");
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add("in");
            observer.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.12, rootMargin: "0px 0px -6% 0px" }
    );
    targets.forEach((el) => observer.observe(el));
    return () => observer.disconnect();
  }, []);

  const visible = category === "All" ? scheduleTemplates : scheduleTemplates.filter((t) => t.category === category);

  return (
    <main className="cs-page tpx-page" id="templates" ref={rootRef}>
      <div className="wx-bg" aria-hidden="true">
        <div className="wx-aurora wx-aurora-1" />
        <div className="wx-aurora wx-aurora-2" />
        <div className="wx-aurora wx-aurora-3" />
      </div>
      <div className="wx-cursor" aria-hidden="true" />

      <section className="cmp-hero tpx-hero" data-reveal>
        <span className="wx-eyebrow">
          <span className="wx-dot" /> Templates
        </span>
        <h1 className="cmp-title">
          <WxTypewriter normal="Start from " em="a proven template." />
        </h1>
        <p className="cmp-sub">
          Skip the blank calendar. Every BuildFlow template is a real construction workflow &mdash; phases, crews, materials, and
          inspections already sequenced &mdash; so your team is scheduling on day one.
        </p>
        <div className="tpx-hero-actions">
          <WxMagnetic className="wx-btn wx-btn-ink" onClick={onGetStarted} ariaLabel="Start free with a template">
            Start free <ArrowRight size={16} />
          </WxMagnetic>
          <WxMagnetic className="wx-btn wx-btn-line" onClick={onContactSales} ariaLabel="Request a custom template">
            Request a custom template
          </WxMagnetic>
        </div>
      </section>

      <section data-reveal>
        <div className="tpx-filter" role="tablist" aria-label="Template categories">
          {templateCategories.map((cat) => (
            <button
              key={cat}
              type="button"
              role="tab"
              aria-selected={category === cat}
              className={`tpx-chip ${category === cat ? "is-active" : ""}`}
              onClick={() => setCategory(cat)}
            >
              {cat}
            </button>
          ))}
        </div>
        <div className="tpx-grid">
          {visible.map((tpl) => {
            const Icon = tpl.icon;
            return (
              <article className="tpx-card" key={tpl.name}>
                <div className="tpx-card-top">
                  <span className="tpx-card-ic">
                    <Icon size={21} />
                  </span>
                  <span className="tpx-tag">{tpl.category}</span>
                </div>
                <h3>{tpl.name}</h3>
                <p>{tpl.desc}</p>
                <div className="tpx-card-foot">
                  <span className="tpx-meta">
                    <Layers size={13} /> {tpl.meta}
                  </span>
                  <button type="button" className="tpx-use" onClick={onGetStarted}>
                    Use template <ArrowRight size={14} />
                  </button>
                </div>
              </article>
            );
          })}
        </div>
      </section>

      <section className="tpx-cta" data-reveal>
        <h2>Don&rsquo;t see your workflow?</h2>
        <p>
          Start from a blank board and BuildFlow shapes it around your crews &mdash; or tell us what you run and we&rsquo;ll build a
          template for you.
        </p>
        <div className="tpx-cta-actions">
          <WxMagnetic className="wx-btn wx-btn-ink" onClick={onGetStarted} ariaLabel="Start from scratch">
            Start from scratch <ArrowRight size={16} />
          </WxMagnetic>
          <WxMagnetic className="wx-btn wx-btn-line" onClick={onContactSales} ariaLabel="Talk to our team">
            Talk to our team
          </WxMagnetic>
        </div>
      </section>

      <WelcomeSharedFooter onBack={onBack} onGetStarted={onGetStarted} onContactSales={onContactSales} />
    </main>
  );
}

