function WelcomeDemoPlayer({ data }: { data?: BootstrapPayload }) {
  const [activeSceneIndex, setActiveSceneIndex] = useState(0);
  const [isPlaying, setIsPlaying] = useState(true);
  const [prefersReducedMotion, setPrefersReducedMotion] = useState(false);
  const activeScene = welcomeDemoScenes[activeSceneIndex];

  useEffect(() => {
    if (typeof window === "undefined" || !window.matchMedia) return;
    const media = window.matchMedia("(prefers-reduced-motion: reduce)");
    setPrefersReducedMotion(media.matches);
    const handleChange = () => setPrefersReducedMotion(media.matches);
    media.addEventListener?.("change", handleChange);
    return () => media.removeEventListener?.("change", handleChange);
  }, []);

  useEffect(() => {
    if (!isPlaying || prefersReducedMotion) return;
    const timer = window.setInterval(() => {
      setActiveSceneIndex((current) => (current + 1) % welcomeDemoScenes.length);
    }, 3600);
    return () => window.clearInterval(timer);
  }, [isPlaying, prefersReducedMotion]);

  const showScene = (index: number) => {
    setActiveSceneIndex(index);
    setIsPlaying(false);
  };

  return (
    <section className="welcome-demo-player" id="dashboard-preview" aria-label="BuildFlow guided demo">
      <div className="welcome-browser-bar">
        <span />
        <span />
        <span />
        <strong>BuildFlow HQ</strong>
        <div className="welcome-browser-actions" aria-hidden="true">
          <span>Share</span>
          <Bell size={16} />
          <Sparkles size={16} />
        </div>
      </div>
      <div className={`welcome-demo-stage ${activeScene.id}`}>
        <aside className="welcome-demo-sidebar">
          <div className="demo-side-brand">
            <BuildFlowLogoMark />
            <strong>BuildFlow</strong>
          </div>
          <div className="demo-side-summary">
            <span>Today</span>
            <strong>{data?.jobs.length ?? 8}</strong>
            <em>active jobs</em>
          </div>
          <nav className="demo-side-nav" aria-label="Demo walkthrough">
            {welcomeDemoScenes.map((scene, index) => (
              <button
                key={scene.id}
                className={index === activeSceneIndex ? "active" : ""}
                onClick={() => showScene(index)}
                aria-label={`Open ${scene.label} demo`}
              >
                {index === 0 && <Grid2X2 size={16} />}
                {index === 1 && <CalendarDays size={16} />}
                {index === 2 && <PackageCheck size={16} />}
                {index === 3 && <ClipboardList size={16} />}
                {index === 4 && <MapPin size={16} />}
                {index === 5 && <LineChart size={16} />}
                {scene.label}
              </button>
            ))}
          </nav>
          <div className="demo-side-agents">
            <span>Field assistants</span>
            <p>
              <Timer size={15} /> Dispatch watcher
            </p>
            <p>
              <PackageCheck size={15} /> Readiness agent
            </p>
            <p>
              <Route size={15} /> Route planner
            </p>
          </div>
        </aside>
        <div className="welcome-demo-screen">
          <div className="demo-app-heading">
            <div>
              <span className="welcome-demo-kicker">{activeScene.label}</span>
              <h2>{activeScene.title}</h2>
              <p>{activeScene.caption}</p>
            </div>
            <button>
              New <ChevronDown size={15} />
            </button>
          </div>
          <div className="demo-app-tabs" aria-hidden="true">
            <span className="active">
              <Grid2X2 size={15} /> Company tasks
            </span>
            <span>
              <Users size={15} /> Crews
            </span>
            <span>
              <Route size={15} /> Routes
            </span>
            <span>
              <LineChart size={15} /> Timeline
            </span>
          </div>
          <WelcomeDemoScene key={activeScene.id} sceneId={activeScene.id} data={data} />
          <WelcomeDemoHelpers sceneId={activeScene.id} />
          <div className="welcome-demo-cursor" aria-hidden="true">
            <MousePointer2 size={22} />
          </div>
          <button
            className="welcome-demo-play"
            onClick={() => setIsPlaying((current) => !current)}
            aria-label={isPlaying ? "Pause demo" : "Play demo"}
          >
            <span>{isPlaying ? <PauseCircle size={22} /> : <PlayCircle size={22} />}</span>
            <strong>{isPlaying ? "Pause tour" : "Play tour"}</strong>
            <em>⌘0</em>
          </button>
        </div>
      </div>
      <div className="welcome-demo-controls" aria-label="Demo scenes">
        {welcomeDemoScenes.map((scene, index) => (
          <button
            key={scene.id}
            className={index === activeSceneIndex ? "active" : ""}
            onClick={() => showScene(index)}
            aria-label={`Show ${scene.label} demo`}
            aria-pressed={index === activeSceneIndex}
          >
            <span>{String(index + 1).padStart(2, "0")}</span>
            {scene.label}
          </button>
        ))}
      </div>
    </section>
  );
}

