// Subtle cursor-driven 3D tilt, mirroring the welcome page's floating windows.

// Shared "Antigravity" HUD motion: cursor parallax (aurora + tint) and scroll
// reveals. Progressive enhancement — `dx-ready` turns on the hidden start state
// only once JS runs, so content is never stuck invisible without JS.
/* Modal dialog semantics (ARIA APG) for the reskinned `.pdx` dialogs: they claim
   aria-modal, so they also have to own the keyboard — move focus in on open, keep
   Tab inside, close on Escape, and hand focus back to whatever opened it.
   `isOpen` lets a page that renders more than one dialog call this once. */
function useModalDialog(dialogRef: React.RefObject<HTMLElement | null>, onClose: () => void, isOpen: boolean) {
  // Kept in a ref so the effect can run on open/close only. With `onClose` as a
  // dependency it re-ran on every parent render and its cleanup pulled focus
  // back out of the dialog.
  const onCloseRef = useRef(onClose);
  onCloseRef.current = onClose;

  useEffect(() => {
    if (!isOpen) return;
    const opener = document.activeElement as HTMLElement | null;
    const focusables = () => {
      const root = dialogRef.current;
      if (!root) return [] as HTMLElement[];
      return Array.from(
        root.querySelectorAll<HTMLElement>('input, select, textarea, button:not([disabled]), [href], [tabindex]:not([tabindex="-1"])')
      ).filter((el) => el.offsetParent !== null || el === document.activeElement);
    };

    // Prefer the first form control over the close button, which precedes it in
    // the DOM: landing a data-entry dialog on "close" is a dead-end first stop.
    const firstField = dialogRef.current?.querySelector<HTMLElement>(".pdx-form input, .pdx-form select, .pdx-form textarea");
    (firstField ?? focusables()[0])?.focus();

    const onKeyDown = (event: globalThis.KeyboardEvent) => {
      if (event.key === "Escape") {
        event.stopPropagation();
        onCloseRef.current();
        return;
      }
      if (event.key !== "Tab") return;
      const items = focusables();
      if (items.length === 0) return;
      const first = items[0];
      const last = items[items.length - 1];
      const active = document.activeElement as HTMLElement | null;
      // Wrap at both ends, and pull focus back if it has escaped the dialog.
      if (event.shiftKey && (active === first || !dialogRef.current?.contains(active))) {
        event.preventDefault();
        last.focus();
      } else if (!event.shiftKey && (active === last || !dialogRef.current?.contains(active))) {
        event.preventDefault();
        first.focus();
      }
    };

    document.addEventListener("keydown", onKeyDown, true);
    return () => {
      document.removeEventListener("keydown", onKeyDown, true);
      opener?.focus?.();
    };
  }, [isOpen, dialogRef]);
}

type CcTone = "blue" | "green" | "amber" | "red" | "violet" | "orange";

// Lightweight inline SVG sparkline — colored via a `tone-*` class (currentColor).
function Sparkline({ data, tone = "blue" }: { data: number[]; tone?: CcTone }) {
  const w = 100;
  const h = 30;
  const max = Math.max(...data);
  const min = Math.min(...data);
  const span = max - min || 1;
  const step = w / (data.length - 1);
  const points = data.map((value, index) => {
    const x = index * step;
    const y = h - ((value - min) / span) * (h - 6) - 3;
    return `${x.toFixed(1)},${y.toFixed(1)}`;
  });
  const line = `M${points.join(" L")}`;
  const area = `${line} L${w},${h} L0,${h} Z`;
  return (
    <svg className={`cc-spark tone-${tone}`} viewBox={`0 0 ${w} ${h}`} preserveAspectRatio="none" aria-hidden="true">
      <path className="cc-spark-fill" d={area} />
      <path className="cc-spark-line" d={line} />
    </svg>
  );
}

// ============================================================================
// Draggable dashboard layout — per-user, client-only persistence.
//
// Each user can rearrange their Command Center: drag any panel into any slot
// of any row (a row holds up to three side by side) or onto the seam between
// rows to give it a row of its own, and reorder the individual metric cards
// within the Performance and KPI rows (side to side). The layout is saved to
// localStorage keyed by the active user's id, so it lives only on that
// person's device and is NEVER written to the shared company backend — one
// user's layout can't affect anyone else's.
// ============================================================================
type DashScope = "section" | "stats" | "kpis";

