// Scan the whole program for the highest-leverage things a PM should act on.
// Grounded in authoritative status fields (not clock math) so it's always right.
function buildOptimizationSuggestions(data: BootstrapPayload): string[] {
  const projectName = (id: string) => data.projects.find((p) => p.id === id)?.name ?? "a project";
  const out: string[] = [];

  const overbooked = data.crews.filter((c) => c.status === "Overbooked" || c.utilization >= 90);
  const underused = data.crews.filter((c) => c.status === "Available" || c.utilization <= 55);
  if (overbooked.length) {
    const worst = [...overbooked].sort((a, b) => b.utilization - a.utilization)[0];
    const free = [...underused].sort((a, b) => a.utilization - b.utilization)[0];
    out.push(
      free
        ? `Rebalance crews: ${worst.name} is at ${worst.utilization}% while ${free.name} sits at ${free.utilization}% — shifting a job would relieve the bottleneck.`
        : `${worst.name} is overbooked at ${worst.utilization}% — add capacity or resequence its jobs.`
    );
  }

  const blockedJobs = data.jobs.filter((j) => j.materialsStatus === "Missing" || j.materialsStatus === "Waiting on Delivery");
  if (blockedJobs.length) {
    out.push(
      `${blockedJobs.length} job${blockedJobs.length > 1 ? "s are" : " is"} blocked on materials (e.g. “${blockedJobs[0].name}” — ${blockedJobs[0].materialsStatus}). Expedite delivery or resequence work that can proceed.`
    );
  }

  const highDelayIQs = data.delayIQs.filter((d) => d.status !== "Resolved" && d.severity === "High");
  if (highDelayIQs.length) {
    const worst = [...highDelayIQs].sort((a, b) => b.impactDays - a.impactDays)[0];
    out.push(
      `Tackle the “${worst.title}” delayIQ on ${projectName(worst.projectId)} first — it's High severity and adds ${worst.impactDays} day${worst.impactDays === 1 ? "" : "s"}.`
    );
  }

  const conflicts = data.assignments.filter((a) => a.conflicts && a.conflicts.length > 0);
  if (conflicts.length) {
    out.push(
      `Resolve ${conflicts.length} schedule conflict${conflicts.length > 1 ? "s" : ""} in the crew assignments before they cascade.`
    );
  }

  const openReadiness = data.readiness.filter((r) => !r.complete);
  if (openReadiness.length) {
    out.push(
      `Close out ${openReadiness.length} open readiness item${openReadiness.length > 1 ? "s" : ""} (e.g. “${openReadiness[0].label}” on ${projectName(openReadiness[0].projectId)}) so ready work isn't held up.`
    );
  }

  const upcomingInspections = data.inspections.filter((i) => i.status === "Upcoming");
  if (upcomingInspections.length) {
    out.push(
      `Confirm crews and access for ${upcomingInspections.length} upcoming inspection${upcomingInspections.length > 1 ? "s" : ""} (e.g. “${upcomingInspections[0].title}” on ${projectName(upcomingInspections[0].projectId)}).`
    );
  }

  const weather = data.weatherAlerts.filter((w) => w.severity === "High" || w.severity === "Medium");
  if (weather.length) {
    out.push(
      `Watch weather: “${weather[0].title}” (${weather[0].severity})${weather[0].projectId ? ` near ${projectName(weather[0].projectId)}` : ""} — line up indoor tasks as a backup.`
    );
  }

  const atRisk = data.projects.filter((p) => p.scheduleHealth === "At Risk");
  if (atRisk.length) {
    out.push(
      `Review ${atRisk.length} at-risk project${atRisk.length > 1 ? "s" : ""}: ${atRisk
        .slice(0, 3)
        .map((p) => p.name)
        .join(", ")}.`
    );
  }

  return out;
}

// Turn a free-text question into a data-grounded answer over the whole program.
function buildAiAnswer(question: string, data: BootstrapPayload): AiAnswer {
  const aiStarters = aiStartersFor(tradeProfileFor(readStoredBusinessType()));
  const q = question.toLowerCase();
  const has = (...words: string[]) => words.some((w) => q.includes(w));
  const projectName = (id: string) => data.projects.find((p) => p.id === id)?.name ?? "a project";
  const crewName = (id: string) => data.crews.find((c) => c.id === id)?.name ?? "a crew";
  const jobName = (id: string) => data.jobs.find((j) => j.id === id)?.name ?? "a job";
  const userName = (id: string) => data.users.find((u) => u.id === id)?.name ?? "someone";
  const followups = ["What's at risk?", "How's crew capacity?", "Suggestions to optimize my week"];

  // Suggestions / optimization
  if (has("suggest", "optimi", "recommend", "improve", "advice", "prioriti", "what should i", "focus on", "help me")) {
    const suggestions = buildOptimizationSuggestions(data);
    if (!suggestions.length) {
      return {
        text: `Everything looks healthy across your ${data.projects.length} projects — no urgent risks, blocked materials, or overbooked crews right now.`
      };
    }
    return {
      text: "Here's where I'd focus to keep your projects moving:",
      bullets: suggestions,
      suggestions: (tradeProfileFor(readStoredBusinessType())?.aiStarters ?? GENERIC_AI_STARTERS).slice(0, 3)
    };
  }

  // How-to (instructional) — checked before data domains so "how do I add a crew"
  // isn't read as a crew-status query. Spans the whole app, not just scheduling.
  if (
    has(
      "how do i",
      "how do you",
      "how to",
      "how can i",
      "how does",
      "where do i",
      "where can i",
      "show me how",
      "walk me through",
      "steps to",
      "guide me",
      "set up",
      "turn on",
      "enable",
      "get started",
      "how to use"
    )
  ) {
    const hit = AI_FEATURE_HELP.find((f) => f.keys.some((k) => q.includes(k)));
    if (hit)
      return {
        text: hit.text,
        suggestions: ["How do I create a project?", "How do I import my schedule?", "Suggestions to optimize my week"]
      };
    return {
      text: "I can walk you through pretty much anything in BuildFlow — not just scheduling. A few areas:",
      bullets: [
        "Scheduling — assign crews, publish the week, fix conflicts",
        "Projects, crews, equipment & people — create and manage them",
        "Materials, readiness & field updates — track work as it runs",
        "DelayIQ, inspections & weather — stay ahead of risk",
        "Map & routes, TimeCard, and exporting Reports",
        "BuildFlow AI — import a schedule from another app, or optimize your week",
        "Settings & billing — plans, notifications, connections"
      ],
      suggestions: ["How do I create a project?", "How do I import my schedule?", "How do I export a report?", "How do I add a crew?"]
    };
  }

  // At risk
  if (has("risk", "attention", "problem", "issue", "concern", "worry", "trouble", "red flag")) {
    const bullets: string[] = [];
    data.projects
      .filter((p) => p.scheduleHealth === "At Risk")
      .forEach((p) => bullets.push(`Project at risk: ${p.name} (${p.percentComplete}% complete)`));
    data.delayIQs
      .filter((d) => d.status !== "Resolved" && d.severity === "High")
      .forEach((d) => bullets.push(`High delayIQ: ${d.title} on ${projectName(d.projectId)} (+${d.impactDays}d)`));
    data.jobs
      .filter((j) => j.materialsStatus === "Missing")
      .forEach((j) => {
        const proj = projectName(j.projectId);
        bullets.push(`Missing materials: ${j.name}${j.name === proj ? "" : ` on ${proj}`}`);
      });
    data.assignments
      .filter((a) => a.conflicts && a.conflicts.length > 0)
      .forEach((a) => bullets.push(`Schedule conflict: ${jobName(a.jobId)} → ${crewName(a.crewId)}`));
    if (!bullets.length) return { text: "Nothing is flagged at risk right now — projects are On Track or better.", suggestions: followups };
    return {
      text: `${bullets.length} thing${bullets.length > 1 ? "s" : ""} I'd keep an eye on:`,
      bullets: bullets.slice(0, 8),
      suggestions: ["What should I prioritize?", "How's crew capacity?"]
    };
  }

  // DelayIQs
  if (has("delayIQ", "behind", "slip", "running late", "over schedule")) {
    const open = data.delayIQs.filter((d) => d.status !== "Resolved");
    if (!open.length)
      return { text: `No open delayIQs right now — all ${data.delayIQs.length} logged delayIQs are resolved.`, suggestions: followups };
    const totalDays = open.reduce((sum, d) => sum + d.impactDays, 0);
    return {
      text: `${open.length} open delayIQ${open.length > 1 ? "s" : ""} adding up to ${totalDays} day${totalDays === 1 ? "" : "s"} of impact:`,
      bullets: [...open]
        .sort((a, b) => b.impactDays - a.impactDays)
        .map((d) => `${d.title} — ${projectName(d.projectId)} · ${d.severity} · +${d.impactDays}d · ${d.status}`),
      suggestions: ["What should I prioritize?", "What's at risk?"]
    };
  }

  // Crews / capacity
  if (
    has("crew", "rebalance", "overbook", "utiliz", "who's free", "who is free", "capacity", "staff", "workload", "workforce", "manpower")
  ) {
    const crews = [...data.crews].sort((a, b) => b.utilization - a.utilization);
    const overbooked = crews.filter((c) => c.status === "Overbooked" || c.utilization >= 90);
    const available = crews.filter((c) => c.status === "Available" || c.utilization <= 55);
    let text = `You have ${data.crews.length} crews.`;
    if (overbooked.length && available.length)
      text += ` ${overbooked[0].name} is stretched at ${overbooked[0].utilization}% while ${available[available.length - 1].name} has room at ${available[available.length - 1].utilization}% — a good rebalance.`;
    else if (overbooked.length) text += ` ${overbooked[0].name} is overbooked at ${overbooked[0].utilization}%.`;
    else text += " Utilization looks balanced.";
    return {
      text,
      bullets: crews.map((c) => `${c.name} (${c.specialty}) — ${c.utilization}% · ${c.status} · lead ${c.lead}`),
      suggestions: ["Suggestions to optimize my week", "What's scheduled this week?"]
    };
  }

  // Materials
  if (has("material", "supply", "supplies", "deliver", "shortage", "concrete", "rebar", "order")) {
    const byStatus = (s: Material["status"]) => data.materials.filter((m) => m.status === s);
    const missing = byStatus("Missing");
    const waiting = byStatus("Waiting on Delivery");
    const problem = [...missing, ...waiting];
    const text = `Materials: ${byStatus("Ready").length} ready, ${byStatus("Ordered").length} ordered, ${waiting.length} awaiting delivery, ${missing.length} missing.`;
    if (!problem.length) return { text: `${text} Nothing is blocking work.`, suggestions: followups };
    return {
      text: `${text} Watch these:`,
      bullets: problem.map(
        (m) => `${m.name} — ${projectName(m.projectId)} · ${m.status}${m.deliveryDate ? ` · due ${m.deliveryDate}` : ""}`
      ),
      suggestions: ["What should I prioritize?", "What's at risk?"]
    };
  }

  // Readiness
  if (has("readiness", "ready to start", "prep", "prereq", "are we ready", "cleared")) {
    const incomplete = data.readiness.filter((r) => !r.complete);
    const text = `Readiness: ${data.readiness.length - incomplete.length} of ${data.readiness.length} items complete.`;
    if (!incomplete.length) return { text: `${text} Everything's cleared to start.`, suggestions: followups };
    return {
      text: `${text} Still open:`,
      bullets: incomplete.map((r) => `${r.label} — ${projectName(r.projectId)}${r.dueDate ? ` · due ${r.dueDate}` : ""}`),
      suggestions: ["What should I prioritize?"]
    };
  }

  // Schedule / this week
  if (has("schedule", "this week", "today", "activit", "assignment", "scheduled", "agenda", "what's on", "whats on")) {
    const conflicts = data.assignments.filter((a) => a.conflicts && a.conflicts.length > 0);
    return {
      text: `${data.assignments.length} scheduled assignment${data.assignments.length === 1 ? "" : "s"}${conflicts.length ? `, ${conflicts.length} with conflicts` : ""}.`,
      bullets: data.assignments
        .slice(0, 8)
        .map(
          (a) =>
            `${jobName(a.jobId)} → ${crewName(a.crewId)} · ${a.date} · ${a.status}${a.conflicts && a.conflicts.length ? " · ⚠ conflict" : ""}`
        ),
      suggestions: ["How's crew capacity?", "What's at risk?"]
    };
  }

  // Weather
  if (has("weather", "rain", "storm", "wind", "forecastIQ", "cold", "heat")) {
    if (!data.weatherAlerts.length) return { text: "No active weather alerts.", suggestions: followups };
    return {
      text: `${data.weatherAlerts.length} weather alert${data.weatherAlerts.length > 1 ? "s" : ""}:`,
      bullets: data.weatherAlerts.map(
        (w) => `${w.title} — ${w.severity}${w.projectId ? ` · ${projectName(w.projectId)}` : ""}${w.startsAt ? ` · ${w.startsAt}` : ""}`
      ),
      suggestions: ["What's at risk?"]
    };
  }

  // Inspections
  if (has("inspect")) {
    const pending = data.inspections.filter((i) => i.status !== "Complete");
    if (!pending.length) return { text: "No pending inspections — all complete.", suggestions: followups };
    return {
      text: `${pending.length} inspection${pending.length > 1 ? "s" : ""} pending:`,
      bullets: pending.map((i) => `${i.title} — ${projectName(i.projectId)} · ${i.status}${i.scheduledAt ? ` · ${i.scheduledAt}` : ""}`),
      suggestions: ["What should I prioritize?"]
    };
  }

  // Equipment
  if (has("equipment", "machine", "excavator", "fleet", "gear")) {
    const count = (s: Equipment["status"]) => data.equipment.filter((e) => e.status === s).length;
    return {
      text: `${data.equipment.length} equipment items · ${count("Available")} available, ${count("In Use")} in use, ${count("Maintenance")} in maintenance.`,
      bullets: data.equipment.map((e) => `${e.name} (${e.type}) — ${e.status}${e.assignedTo ? ` · ${e.assignedTo}` : ""}`),
      suggestions: followups
    };
  }

  // Field updates
  if (has("field", "site report", "from the field", "crew report", "latest update", "what's happening", "whats happening")) {
    if (!data.fieldUpdates.length) return { text: "No field updates yet.", suggestions: followups };
    return {
      text: "Latest field updates:",
      bullets: [...data.fieldUpdates]
        .slice(-6)
        .reverse()
        .map((f) => `${projectName(f.projectId)} · ${userName(f.userId)}: ${f.message} (${f.status})`),
      suggestions: ["What's at risk?"]
    };
  }

  // Milestones / deadlines
  if (has("milestone", "deadline", "due date", "target", "completion", "finish", "handover", "hand over")) {
    const phases = [...data.phases].sort((a, b) => a.endDate.localeCompare(b.endDate));
    return {
      text: "Targets and upcoming phase milestones:",
      bullets: [
        ...data.projects.map((p) => `${p.name} — target ${p.targetCompletion} (${p.percentComplete}%)`),
        ...phases.slice(0, 4).map((ph) => `${projectName(ph.projectId)} · ${ph.name} ends ${ph.endDate} · ${ph.status}`)
      ].slice(0, 8),
      suggestions: ["What's at risk?", "Suggestions to optimize my week"]
    };
  }

  // Projects / portfolio / status
  if (has("project", "portfolio", "on track", "how many", "status", "overall", "health", "progress")) {
    const byHealth = (h: Project["scheduleHealth"]) => data.projects.filter((p) => p.scheduleHealth === h);
    const avg = data.projects.length ? Math.round(data.projects.reduce((s, p) => s + p.percentComplete, 0) / data.projects.length) : 0;
    return {
      text: `${data.projects.length} projects · avg ${avg}% complete · ${byHealth("On Track").length} on track, ${byHealth("Monitor").length} to monitor, ${byHealth("At Risk").length} at risk.`,
      bullets: data.projects.map((p) => `${p.name} — ${p.percentComplete}% · ${p.scheduleHealth} · ${p.status}`),
      suggestions: ["What's at risk?", "Suggestions to optimize my week"]
    };
  }

  // Capabilities / greeting
  if (
    has("what can you", "what do you do", "who are you", "capab", "hello", "hey", "how do you work") ||
    q.trim() === "hi" ||
    q.startsWith("hi ")
  ) {
    return {
      text: "I'm your BuildFlow assistant. I read your live projects, crews, schedule, delayIQs, readiness, materials, inspections, and weather — ask about any of them, or ask for suggestions to optimize your week.",
      suggestions: aiStarters
    };
  }

  // Fallback: a quick grounded read + what's worth attention.
  const suggestions = buildOptimizationSuggestions(data);
  const open = data.delayIQs.filter((d) => d.status !== "Resolved").length;
  return {
    text: `Here's a quick read on your ${data.projects.length} projects (${data.crews.length} crews, ${open} open delayIQ${open === 1 ? "" : "s"}), and a few things worth your attention:`,
    bullets: suggestions.length ? suggestions.slice(0, 4) : ["Nothing urgent flagged right now."],
    suggestions: aiStarters
  };
}

// The Command Center's "Ask BuildFlow AI" prompt. Users can attach images by
// dragging them onto the prompt or clicking the "+" button; thumbnail previews
// render below the field and can be removed individually.
// Minimal shape of the browser SpeechRecognition instance used for voice input.
/** The Web Speech API result and error events, as much of them as the mic button reads. */
type SpeechRecognitionEventLike = { results: ArrayLike<{ isFinal: boolean; 0: { transcript: string } }> };
type SpeechRecognitionErrorLike = { error: string };
type SpeechRecognitionLike = {
  lang: string;
  interimResults: boolean;
  continuous: boolean;
  maxAlternatives: number;
  start: () => void;
  stop: () => void;
  abort?: () => void;
  onstart: (() => void) | null;
  onresult: ((event: SpeechRecognitionEventLike) => void) | null;
  onerror: ((event: SpeechRecognitionErrorLike) => void) | null;
  onend: (() => void) | null;
};

// A representative construction schedule "read" from an uploaded photo/video of
// another scheduler. These become REAL projects + jobs + crew assignments through
// the backend, so they land on the live BuildFlow schedule. (Swapping this for a
// real Claude-vision extraction of the actual media is the natural upgrade.)
type ImportJobSpec = Omit<CreateJobInput, "projectId"> & { crewId?: string };
type ImportProjectSpec = { input: CreateProjectInput; jobs: ImportJobSpec[] };

// Read an object-URL-backed attachment blob into a base64 data URL for Claude vision.
function blobToDataUrl(blob: Blob): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = () => reject(reader.error);
    reader.readAsDataURL(blob);
  });
}

