function ReportsPage({ data }: { data: BootstrapPayload }) {
  /* Every figure below is computed from the workspace's own records. Each one
     names what it counted in `basis`, so a number that reads oddly can be traced
     without opening the code — and an empty workspace says "no data yet" instead
     of a confident zero. */
  const reportMetrics = useMemo(() => {
    const calendar = scheduleCalendar(data.jobs.reduce((min, job) => (job.startDate < min ? job.startDate : min), dashboardToday));

    // 1. On-time completion: finished jobs that landed on or before their planned end.
    const finished = data.jobs.filter((job) => job.actualFinish);
    const onTime = finished.filter((job) => (job.actualFinish as string) <= job.endDate);
    // 2. Schedule variance: mean working days each unfinished job's forecast slips.
    const running = data.jobs.filter((job) => !job.actualFinish);
    const slips = running.map(
      (job) => calendar.toIndex(forecastIQFinish(job, job.percentComplete, dashboardToday, calendar)) - calendar.toIndex(job.endDate)
    );
    const avgSlip = slips.length ? slips.reduce((sum, n) => sum + n, 0) / slips.length : 0;
    // 3/4. Utilization straight off the crew and equipment records.
    const crewUtil = data.crews.length ? Math.round(data.crews.reduce((sum, crew) => sum + crew.utilization, 0) / data.crews.length) : 0;
    const inUse = data.equipment.filter((item) => item.status === "In Use").length;
    const equipUtil = data.equipment.length ? Math.round((inUse / data.equipment.length) * 100) : 0;
    // 5. Labor hours: the same model the TimeCard page totals, so the two agree.
    const timecard = buildTimecardModel(data);
    const laborHours = totalsFor(timecard.entries, timecard.workerById).totalHours;
    // 6. Backlog: the planned work still outstanding on unfinished jobs, measured
    //    against each job's OWN duration rather than the calendar ahead of it —
    //    an overdue job still carries its unfinished work, and counting remaining
    //    calendar days reported 0 for a whole seed of past-due jobs. BuildFlow
    //    holds no contract values, so this is a duration backlog, not a dollar one.
    const backlogDays = running.reduce((sum, job) => {
      const duration = Math.max(1, calendar.toIndex(job.endDate) - calendar.toIndex(job.startDate) + 1);
      return sum + Math.round(duration * ((100 - job.percentComplete) / 100));
    }, 0);
    // Priced projects report backlog in dollars: contract value × the share still
    // to build. Projects left unpriced are excluded rather than counted as $0, and
    // if none are priced the metric falls back to the duration figure.
    const priced = data.projects.filter((project) => typeof project.value === "number" && project.value > 0);
    const backlogValue = priced.reduce((sum, project) => sum + (project.value as number) * ((100 - project.percentComplete) / 100), 0);
    const money = (amount: number) =>
      amount >= 1_000_000
        ? `$${(amount / 1_000_000).toFixed(1)}M`
        : amount >= 1_000
          ? `$${Math.round(amount / 1_000)}K`
          : `$${Math.round(amount)}`;
    const backlog = priced.length
      ? {
          label: "Active Backlog",
          value: money(backlogValue),
          basis:
            priced.length === data.projects.length
              ? `Unbuilt value across ${priced.length} projects`
              : `Unbuilt value · ${priced.length} of ${data.projects.length} projects priced`
        }
      : {
          label: "Active Backlog",
          value: running.length ? `${backlogDays.toLocaleString()} days` : "—",
          basis: running.length ? `Remaining work on ${running.length} open jobs · add contract values for dollars` : "No open jobs"
        };

    return [
      {
        label: "On-Time Completion Rate",
        value: finished.length ? `${Math.round((onTime.length / finished.length) * 100)}%` : "—",
        basis: finished.length ? `${onTime.length} of ${finished.length} finished jobs` : "No finished jobs yet"
      },
      {
        label: "Avg. Schedule Variance",
        value: running.length ? `${Math.abs(avgSlip).toFixed(1)} days` : "—",
        basis: running.length
          ? `${avgSlip > 0 ? "behind" : avgSlip < 0 ? "ahead" : "on plan"} across ${running.length} running jobs`
          : "No running jobs"
      },
      {
        label: "Crew Utilization",
        value: data.crews.length ? `${crewUtil}%` : "—",
        basis: data.crews.length ? `Average across ${data.crews.length} crews` : "No crews yet"
      },
      {
        label: "Equipment Utilization",
        value: data.equipment.length ? `${equipUtil}%` : "—",
        basis: data.equipment.length ? `${inUse} of ${data.equipment.length} assets in use` : "No equipment yet"
      },
      {
        label: "Total Labor Hours",
        value: laborHours ? Math.round(laborHours).toLocaleString() : "—",
        basis: laborHours ? "Logged this week" : "No hours logged"
      },
      backlog
    ];
  }, [data]);
  const plannedActualHours = [
    { month: "Jan", planned: 4200, actual: 3850 },
    { month: "Feb", planned: 4450, actual: 4250 },
    { month: "Mar", planned: 4800, actual: 4700 },
    { month: "Apr", planned: 5250, actual: 4900 },
    { month: "May", planned: 5650, actual: 5100 }
  ];
  const backlogForecastIQ = [
    { month: "Jun", backlog: 5200 },
    { month: "Jul", backlog: 6100 },
    { month: "Aug", backlog: 5800 },
    { month: "Sep", backlog: 4900 },
    { month: "Oct", backlog: 4200 },
    { month: "Nov", backlog: 3600 }
  ];
  const crewEfficiency = [
    { name: data.crews.find((crew) => crew.name === "Concrete Crew 1")?.name ?? "Concrete Crew 1", value: 94 },
    { name: "Framing Crew 2", value: 88 },
    { name: "Utility Crew 3", value: 81 },
    { name: "Paving Crew 4", value: 76 }
  ];

  return (
    <div className="page-stack reports-page">
      <PageTitle
        title="Reports"
        subtitle="Production analytics, utilization, and backlog ForecastIQ."
        tutorialId="reports-page-title"
        actions={
          <div className="reports-actions">
            <select defaultValue="last-6-months" aria-label="Report period">
              <option value="last-6-months">Last 6 Months</option>
              <option value="last-quarter">Last Quarter</option>
              <option value="year-to-date">Year to Date</option>
            </select>
            <button type="button">
              <Download size={18} />
              Export
            </button>
          </div>
        }
      />

      <ScheduleStatusBand compact projects={data.projects} />

      <section className="reports-kpi-grid" aria-label="Report summary">
        {reportMetrics.map((metric) => (
          <article className="reports-kpi-card" key={metric.label}>
            <span>{metric.label}</span>
            <strong>{metric.value}</strong>
            {/* what the figure counted, in place of the old hardcoded trend arrow —
                these metrics have no stored history to trend against yet */}
            <em className="reports-kpi-basis">{metric.basis}</em>
          </article>
        ))}
      </section>

      <section className="reports-chart-grid" aria-label="Report charts">
        <article className="reports-card reports-chart-card">
          <header>
            <h2>Planned vs Actual Hours</h2>
          </header>
          <div className="reports-chart-canvas">
            <ResponsiveContainer width="100%" height={260}>
              <BarChart data={plannedActualHours} barGap={8} margin={{ top: 10, right: 18, bottom: 4, left: -8 }}>
                <CartesianGrid stroke="#dde6ef" strokeDasharray="4 6" vertical={false} />
                <XAxis dataKey="month" axisLine={false} tickLine={false} tick={{ fill: "#94a4b8", fontSize: 12 }} />
                <YAxis
                  axisLine={false}
                  tickLine={false}
                  ticks={[0, 1500, 3000, 4500, 6000]}
                  domain={[0, 6500]}
                  tick={{ fill: "#94a4b8", fontSize: 12 }}
                />
                <Tooltip cursor={{ fill: "rgba(9, 32, 56, 0.04)" }} />
                <Bar dataKey="planned" fill="#0a233a" radius={[5, 5, 0, 0]} barSize={22} />
                <Bar dataKey="actual" fill="#2f6bff" radius={[5, 5, 0, 0]} barSize={22} />
              </BarChart>
            </ResponsiveContainer>
            <div className="reports-legend" aria-hidden="true">
              <span>
                <i className="planned" />
                Planned
              </span>
              <span>
                <i className="actual" />
                Actual
              </span>
            </div>
          </div>
        </article>

        <article className="reports-card reports-chart-card">
          <header>
            <h2>Backlog ForecastIQ (Hours)</h2>
          </header>
          <div className="reports-chart-canvas">
            <ResponsiveContainer width="100%" height={260}>
              <RechartsLineChart data={backlogForecastIQ} margin={{ top: 10, right: 18, bottom: 6, left: -8 }}>
                <CartesianGrid stroke="#dde6ef" strokeDasharray="4 6" vertical={false} />
                <XAxis dataKey="month" axisLine={false} tickLine={false} tick={{ fill: "#94a4b8", fontSize: 12 }} />
                <YAxis
                  axisLine={false}
                  tickLine={false}
                  ticks={[0, 2000, 4000, 6000, 8000]}
                  domain={[0, 8200]}
                  tick={{ fill: "#94a4b8", fontSize: 12 }}
                />
                <Tooltip content={<ReportsBacklogTooltip />} cursor={{ stroke: "#ccd5df", strokeWidth: 2 }} />
                <Line
                  type="monotone"
                  dataKey="backlog"
                  stroke="#2f7df6"
                  strokeWidth={3}
                  dot={{ fill: "#2f7df6", r: 5, stroke: "#2f7df6" }}
                  activeDot={{ fill: "#2f7df6", r: 6, stroke: "#ffffff", strokeWidth: 3 }}
                />
              </RechartsLineChart>
            </ResponsiveContainer>
          </div>
        </article>
      </section>

      <section className="reports-card reports-efficiency-card" aria-label="Crew efficiency">
        <header>
          <h2>Crew Efficiency</h2>
        </header>
        <div className="reports-efficiency-list">
          {crewEfficiency.map((crew) => (
            <div className="reports-efficiency-row" key={crew.name}>
              <strong>{crew.name}</strong>
              <span>
                <i style={{ "--crew-efficiency": `${crew.value}%` } as CSSProperties} />
              </span>
              <em>{crew.value}%</em>
            </div>
          ))}
        </div>
      </section>
    </div>
  );
}

