function Badge({ status }: { status: string }) {
  return <span className={`badge ${statusTone(status)}`}>{status}</span>;
}

/**
 * Progress to show on a field update card.
 *
 * A reported percent always wins — that is the crew's own number. Updates filed
 * without one fall back to the position their status implies, so every card
 * carries the meter. This mirrors how Materials draws its "Readiness" bar
 * (materialReadinessProgress below), which is status-derived for the same
 * reason. The fallback is a reading of the status, not a measurement: treat the
 * bar as a coarse indicator unless the update reports a number.
 */
function fieldUpdateProgress(update: FieldUpdate) {
  if (update.percentComplete != null) return update.percentComplete;
  switch (update.status) {
    case "Complete":
      return 100;
    case "On Site":
    case "In Progress":
      return 55;
    case "DelayIQed":
    case "At Risk":
      return 35;
    case "Ready to Start":
    case "Ready":
    case "Confirmed":
      return 15;
    default:
      return 8;
  }
}

function materialReadinessProgress(status: Material["status"]) {
  if (status === "Ready") return 100;
  if (status === "Ordered") return 68;
  if (status === "Waiting on Delivery") return 42;
  return 12;
}

function materialImpact(status: Material["status"]) {
  if (status === "Ready") return "Ready for schedule";
  if (status === "Ordered") return "Procurement tracking";
  if (status === "Waiting on Delivery") return "Watch delivery window";
  return "Blocks affected work";
}

function jobForMaterial(data: BootstrapPayload, material: Material) {
  const matchingStatus = {
    Ready: "Delivered",
    Ordered: "Ordered",
    "Waiting on Delivery": "Waiting on Delivery",
    Missing: "Missing"
  } satisfies Record<Material["status"], Job["materialsStatus"]>;

  return (
    data.jobs.find((job) => job.projectId === material.projectId && job.materialsStatus === matchingStatus[material.status]) ??
    data.jobs.find((job) => job.projectId === material.projectId)
  );
}

function materialReadiness(data: BootstrapPayload) {
  const totals = data.materials.reduce<Record<string, number>>((acc, material) => {
    acc[material.status] = (acc[material.status] ?? 0) + 1;
    return acc;
  }, {});

  return Object.entries(totals).map(([name, value]) => ({
    name,
    value,
    color: statusColors[name as keyof typeof statusColors] ?? "#64748b"
  }));
}

/** "3m ago", "2h ago", "in 4d" — from a real ISO timestamp or a YYYY-MM-DD date. */
/**
 * A cold API, a restarting server or a dropped packet should cost a moment, not
 * an error screen. Retries network failures and 5xx a few times with a short
 * backoff; never retries auth or other 4xx, which mean what they say.
 */
async function retryTransient<T>(run: () => Promise<T>, delaysMs: number[] = [400, 900, 1600]): Promise<T> {
  let attempt = 0;
  for (;;) {
    try {
      return await run();
    } catch (error) {
      const status = error instanceof ApiError ? error.status : undefined;
      const transient = status === undefined ? /could not reach/i.test(error instanceof Error ? error.message : "") : status >= 500;
      if (!transient || attempt >= delaysMs.length) throw error;
      await new Promise((resolve) => setTimeout(resolve, delaysMs[attempt]));
      attempt += 1;
    }
  }
}

/** "7:00 AM" → 420; anything unparseable sorts last. */
function clockMinutes(time: string | undefined) {
  const m = /^(\d{1,2})(?::(\d{2}))?\s*(AM|PM)?$/i.exec((time ?? "").trim());
  if (!m) return Number.MAX_SAFE_INTEGER;
  let hours = Number(m[1]) % 12;
  if (m[3]?.toUpperCase() === "PM") hours += 12;
  return hours * 60 + Number(m[2] ?? 0);
}

function relativeTime(iso: string, now: Date = new Date()) {
  const at = new Date(iso.length === 10 ? `${iso}T12:00:00` : iso);
  if (Number.isNaN(at.getTime())) return "";
  const diffMs = at.getTime() - now.getTime();
  const mins = Math.round(Math.abs(diffMs) / 60000);
  if (mins < 1) return "just now";
  const hours = Math.round(mins / 60);
  const label = mins < 60 ? `${mins}m` : hours < 24 ? `${hours}h` : `${Math.round(mins / 1440)}d`;
  return diffMs < 0 ? `${label} ago` : `in ${label}`;
}

function projectName(data: BootstrapPayload, projectId: string) {
  return data.projects.find((project) => project.id === projectId)?.name ?? "Unassigned";
}

function projectInitials(name: string) {
  const words = name.trim().split(/\s+/).filter(Boolean);
  const first = words[0]?.[0] ?? "";
  const second = words[1]?.[0] ?? words[0]?.[1] ?? "";
  return `${first}${second}`.toUpperCase();
}

function formatDateTime(value: string) {
  return new Intl.DateTimeFormat("en", {
    month: "short",
    day: "numeric",
    hour: "numeric",
    minute: "2-digit"
  }).format(new Date(value));
}

function formatNotificationTimestamp(value: string) {
  if (/^\d{4}-\d{2}-\d{2}$/.test(value)) return formatDate(value);
  return formatDateTime(value);
}

function formatTime(value: string) {
  return new Intl.DateTimeFormat("en", { hour: "numeric", minute: "2-digit" }).format(new Date(value));
}

export default App;
